T2S = {ord(_T2S_PAIRS[i]): _T2S_PAIRS[i + 1] for i in range(0, len(_T2S_PAIRS), 2)}


def simp(text):
    return text.translate(T2S) if isinstance(text, str) else text


def keyword_tags(text):
    tags = Counter()
    if not text:
        return tags
    t = text
    if "适性" in t:  # 适性之力：物攻或魔攻取高者，两种路线都吃
        tags["AD"] += 1
        tags["AP"] += 1
        t = t.replace("适性之力", "　")
    for dim, pats in KEYWORDS:
        for p in pats:
            n = len(re.findall(p, t))
            if n:
                tags[dim] += min(n, 3)
                t = re.sub(p, "　", t)
    return tags


def clean_desc(s):
    s = s or ""
    s = re.sub(r"%i:[^%]*%", "", s)
    s = re.sub(r"<br\s*/?>", " ", s)
    s = re.sub(r"<[^>]+>", "", s)
    s = re.sub(r"@[^@]+@", "X", s)
    s = re.sub(r"\{\{\s*Item_Keyword_OnHit\s*\}\}", "攻击特效", s)
    s = re.sub(r"\{\{[^}]*\}\}", "", s)
    return re.sub(r"\s+", " ", s).strip()


def norm(vec):
    n = math.sqrt(sum(v * v for v in vec.values()))
    return {k: v / n for k, v in vec.items()} if n else {}


def cosine(a, b):
    return sum(a.get(k, 0) * v for k, v in b.items())


def add_into(dst, src, w=1.0):
    for k, v in src.items():
        dst[k] = dst.get(k, 0) + v * w


# --------------------------------------------------------------------------------------
# 网络
# --------------------------------------------------------------------------------------
def write_json(path, data):
    """先写临时文件再换上：程序被关掉或断电时不会留下写了一半的缓存"""
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False)
    os.replace(tmp, path)


def read_json(path):
    """读缓存；文件坏了回传 None（之后会重新下载）"""
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def http_json(url, timeout=10, local=False):
    req = urllib.request.Request(url, headers={"User-Agent": "haidou-helper/1.0"})
    if local:
        ctx = ssl.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE  # 游戏客户端使用自签名证书，且只连本机
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}),
                                             urllib.request.HTTPSHandler(context=ctx))
    else:
        opener = urllib.request.build_opener()
    with opener.open(req, timeout=timeout) as r:
        return json.loads(r.read().decode("utf-8"))


# --------------------------------------------------------------------------------------
# 静态数据
# --------------------------------------------------------------------------------------
class GameData:
    lang = "zh_TW"

    def __init__(self, items=None, champs=None, augments=None, version="?"):
        self.items = items or {}       # id(int) -> ddragon item dict
        self.champs = champs or {}     # lower id -> ddragon champ dict
        self.augments = augments or []  # [{name, desc, rarity, tags}]
        self.version = version
        self._vec_cache = {}

    # ---------- loading ----------
    @classmethod
    def load(cls, lang="zh_CN", log=print):
        os.makedirs(APP_DIR, exist_ok=True)
        version = None
        try:
            version = http_json(DDRAGON + "/api/versions.json")[0]
        except Exception as e:  # noqa
            log(tr('[数据] 无法获取版本号（{0}），尝试使用本地缓存').format(e))

        fresh = {"ok": True}      # 这次该下载的是否都下载成功（失败就不写版本标记，下次再试）

        def cached(name, url, optional=False):
            path = os.path.join(APP_DIR, name)
            if url:
                try:
                    data = http_json(url, timeout=30)
                    write_json(path, data)
                    return data
                except urllib.error.HTTPError as e:
                    if e.code == 404 and optional:  # 备用的增幅来源不存在：记为空，之后不再尝试
                        write_json(path, [])
                        return []
                    log(tr('[数据] 下载失败 {0}: {1}').format(url, e))
                    fresh["ok"] = False
                except Exception as e:  # noqa
                    log(tr('[数据] 下载失败 {0}: {1}').format(url, e))
                    fresh["ok"] = False
            return read_json(path)

        base = f"{DDRAGON}/cdn/{version}/data/{lang}" if version else None
        need_dl = version and not os.path.exists(os.path.join(APP_DIR, f"ver_{version}_{lang}"))
        items_raw = cached(f"item_{lang}.json", base + "/item.json" if need_dl else None)
        champ_raw = cached(f"champion_{lang}.json", base + "/champion.json" if need_dl else None)
        if not isinstance(items_raw, dict) or not isinstance(champ_raw, dict):
            raise RuntimeError(tr("没有装备/英雄数据：请确认能访问 ddragon.leagueoflegends.com 后重试"))
        if need_dl and fresh["ok"]:
            open(os.path.join(APP_DIR, f"ver_{version}_{lang}"), "w").close()

        items = {int(k): v for k, v in items_raw.get("data", {}).items() if k.isdigit()}
        champs = {v["id"].lower(): v for v in champ_raw.get("data", {}).values()}
        for v in items.values():  # 台服名称，转成简体字
            for f in ("name", "description", "plaintext"):
                v[f] = simp(v.get(f, ""))
        for v in champs.values():
            v["name"] = simp(v.get("name", ""))

        aug_lang = lang.lower()
        augs = {}
        current_ids = set()   # 当前版本游戏数据里存在的所有增幅编号
        for i, tmpl in enumerate(AUGMENT_URLS):
            url = tmpl.format(lang=aug_lang, plang=cdragon_lang(lang))
            ap = os.path.join(APP_DIR, f"aug_{i}_{aug_lang}.json")
            stale = not os.path.exists(ap) or os.path.getsize(ap) <= 2 or \
                time.time() - os.path.getmtime(ap) > 24 * 3600      # 每天最多重新读一次；空的（以前地址错）马上重读
            data = cached(f"aug_{i}_{aug_lang}.json", url if version and (need_dl or stale) else None, optional=True)
            for a in cls._parse_augments(data):
                if a.get("current") and a.get("id"):
                    current_ids.add(a["id"])
                old = augs.get(a["name"])
                if not old:
                    augs[a["name"]] = a
                    continue
                # 同名常有两个版本：竞技场版（如 7 BluntForce）和海斗版（如 1007 ARAM_BluntForce）。
                # 编号以海斗版为准（胜率数据用的是它），其次才是当前版本的其他编号。
                if a.get("aram"):
                    old["aram"] = True
                    old["rarity"] = a["rarity"]
                    old["id"] = a.get("id") or old.get("id")
                elif a.get("id") and (not old.get("id") or (a.get("current") and not old.get("aram"))):
                    old["id"] = a["id"]
                if a.get("current"):
                    old["current"] = True
                if not old["desc"] and a["desc"]:
                    old["desc"], old["tags"] = a["desc"], a["tags"]
        for a in cls._local_augments():   # 自己补充的描述：已有的增幅只补描述，不丢掉编号（胜率要用）
            old = augs.get(a["name"])
            if old:
                if a["desc"]:
                    old["desc"], old["tags"] = a["desc"], a["tags"]
            else:
                augs[a["name"]] = a
        if not version:   # 断网：用缓存对应的版本号
            marks = [fn[4:-len(lang) - 1] for fn in os.listdir(APP_DIR)
                     if fn.startswith("ver_") and fn.endswith("_" + lang)]
            version = max(marks, key=lambda v: [int(x) for x in v.split(".") if x.isdigit()], default=None)
        gd = cls(items, champs, list(augs.values()), version or "cache")
        gd.lang = lang
        gd.current_aug_ids = current_ids
        log(tr('[数据] 版本 {0}：装备 {1}，英雄 {2}，增幅 {3}').format(gd.version, len(items), len(champs), len(gd.augments)))
        return gd

    @staticmethod
    def _rarity(r):
        if isinstance(r, (int, float)) or str(r).isdigit():
            return max(0, min(2, int(r)))
        r = str(r).lower()
        return 2 if "prism" in r else 1 if "gold" in r else 0

    @classmethod
    def _parse_augments(cls, data):
        out = []
        if not data:
            return out
        lst = data.get("augments", []) if isinstance(data, dict) else data
        for a in lst:
            if not isinstance(a, dict):
                continue
            name = a.get("name") or a.get("nameTRA")
            if not name:
                continue
            desc = simp(clean_desc(a.get("desc") or a.get("tooltip") or a.get("descriptionTRA") or ""))
            aug = make_aug(simp(name), desc, cls._rarity(a.get("rarity", 0)))
            aug["aram"] = str(a.get("augmentNameId", "")).startswith("ARAM_")  # 海克斯大乱斗专用
            aug["current"] = "augmentNameId" in a   # 来自当前版本游戏数据
            if str(a.get("id", "")).isdigit():
                aug["id"] = int(a["id"])
            out.append(aug)
        return out

    @staticmethod
    def _local_augments():
        out = []
        p = os.path.join(APP_DIR, "augments.json")
        if os.path.exists(p):
            try:
                with open(p, encoding="utf-8-sig") as f:
                    for a in json.load(f):
                        out.append(make_aug(a["name"], clean_desc(a.get("desc", "")),
                                            GameData._rarity(a.get("rarity", 0))))
            except Exception as e:  # noqa
                print(tr("augments.json 解析失败:"), e)
        p = os.path.join(APP_DIR, "augments.txt")
        if os.path.exists(p):
            for enc in ("utf-8-sig", "gbk"):        # 记事本存的可能是 ANSI(GBK)
                try:
                    with open(p, encoding=enc) as f:
                        lines = f.read().splitlines()
                    break
                except (UnicodeDecodeError, OSError):
                    lines = []
            for line in lines:
                line = line.strip()
                if line and not line.startswith("#"):
                    name, _, desc = line.partition("|")
                    out.append(make_aug(name.strip(), desc.strip(), 0))
        return out

    def add_english_names(self, log=print):
        """游戏客户端是英文、但资料是中文时（或反过来），三选一上的英文卡名也要认得：
        按增幅编号把英文名称记为别名（每天最多下载一次，约几百 KB）。"""
        if self.lang.lower().startswith("en"):
            return 0
        path = os.path.join(APP_DIR, "aug_names_en.json")
        data = None
        if not os.path.exists(path) or time.time() - os.path.getmtime(path) > 24 * 3600:
            try:
                raw = http_json(EN_AUGMENT_URL, timeout=20)
                data = {str(a["id"]): a.get("nameTRA") or a.get("name") for a in raw
                        if isinstance(a, dict) and str(a.get("id", "")).isdigit() and (a.get("nameTRA") or a.get("name"))}
                write_json(path, data)
            except Exception as e:  # noqa
                log(tr('[数据] 下载失败 {0}: {1}').format(EN_AUGMENT_URL, e))
        if data is None:
            data = read_json(path) or {}
        n = 0
        for a in self.augments:
            en = data.get(str(a.get("id")))
            if en and en != a["name"] and en not in a.get("aliases", []):
                a.setdefault("aliases", []).append(en)
                n += 1
        return n

    def add_arammayhem(self, am):
        """并入 arammayhem.com：按英文名 / 繁中名 / 简中名对到库里的增幅，
        把各语言名称都记为别名（国服、台服、英文客户端的卡名都认得），再记下国服选取率与推荐组合。"""
        def key(x):
            return re.sub(r"[\s'’\-!.,:：·]", "", simp(str(x))).lower()
        index = {}
        for a in self.augments:
            for n in [a["name"]] + a.get("aliases", []):
                index.setdefault(key(n), a)
        slug_to_id, matched = {}, 0
        for r in am.get("augments", []):
            names = r.get("name") if isinstance(r.get("name"), dict) else \
                {k[5:]: v for k, v in r.items() if k.startswith("name_")}
            a = next((index.get(key(names[lc])) for lc in ("en", "zh-TW", "zh-CN") if names.get(lc)
                      and index.get(key(names[lc]))), None)
            if a is None:
                continue
            matched += 1
            for lc, n in names.items():
                n = simp(n) if lc.startswith("zh") else n
                if n and n != a["name"] and n not in a.setdefault("aliases", []):
                    a["aliases"].append(n)
            if isinstance(r.get("pickRate"), (int, float)):
                a["am_pick"] = r["pickRate"] / 100.0
            slug_to_id[r.get("augmentId")] = a
        combos = {}
        for c in am.get("combos", []):
            types = {str(x).lower() for x in c.get("types", [])}
            kind = "good" if types & AM_GOOD else "bad" if types & AM_BAD else None
            if not kind:
                continue
            for sid in c.get("augmentIds", []):
                a = slug_to_id.get(sid)
                if a is not None:
                    combos[(str(c.get("championId", "")).lower(), a["name"])] = kind
        self.am_combos = combos
        self.am_matched = matched
        return matched

    def merge_augments(self, extra):
        """合并网上的增幅描述（有属性标注，覆盖所有海斗增幅）。
        先按编号对应：名称以当前版本游戏数据为准，网站上的旧名称记为别名。"""
        by = {a["name"]: a for a in self.augments}
        by_id = {a["id"]: a for a in self.augments if a.get("id")}
        for a in extra:
            old = by_id.get(a.get("id")) or by.get(a["name"])
            if old is not None and old["name"] != a["name"]:
                old.setdefault("aliases", []).append(a["name"])
            if old is None and a.get("foreign"):
                continue          # 英文模式下取到的是中文资料，对不上编号的不加进来
            if old is None:
                self.augments.append(a)
                by[a["name"]] = a
            else:
                old["desc"], old["tags"], old["aram"] = a["desc"] or old["desc"], a["tags"] or old["tags"], True
                old["id"] = a.get("id") or old.get("id")
                old["rarity"] = a["rarity"]

    def champ_kit(self, cid):
        """英雄技能名称与描述（Data Dragon，每个英雄只下载一次并缓存）"""
        cache = getattr(self, "_kits", None)
        if cache is None:
            cache = self._kits = {}
        if cid in cache:
            return cache[cid]
        kit = None
        c = self.champ(cid)
        if c and self.version not in ("?", "cache"):
            path = os.path.join(APP_DIR, f"kit_{self.version}_{self.lang}_{c['id']}.json")
            try:
                if os.path.exists(path):
                    with open(path, encoding="utf-8") as f:
                        raw = json.load(f)
                else:
                    raw = http_json(f"{DDRAGON}/cdn/{self.version}/data/{self.lang}/champion/{c['id']}.json", timeout=8)
                    with open(path, "w", encoding="utf-8") as f:
                        json.dump(raw, f, ensure_ascii=False)
                d = next(iter(raw.get("data", {}).values()))
                kit = {k: {"name": simp(sp.get("name", "")), "desc": simp(clean_desc(sp.get("description", "")))}
                       for k, sp in zip("QWER", d.get("spells", []))}
                kit["P"] = {"name": simp(d.get("passive", {}).get("name", "")),
                            "desc": simp(clean_desc(d.get("passive", {}).get("description", "")))}
            except Exception:  # noqa
                kit = None
        cache[cid] = kit
        return kit

    # ---------- queries ----------
    def champ(self, cid):
        return self.champs.get((cid or "").lower())

    def champ_name(self, cid):
        c = self.champ(cid)
        return c["name"] if c else cid

    def item_name(self, iid):
        it = self.items.get(iid)
        return it["name"] if it else str(iid)

    def is_boots(self, iid):
        it = self.items.get(iid)
        return bool(it) and "Boots" in it.get("tags", [])

    def item_desc(self, iid):
        it = self.items.get(iid, {})
        return clean_desc(it.get("description", "")) + " " + it.get("plaintext", "")

    def item_price(self, iid):
        return self.items.get(iid, {}).get("gold", {}).get("total", 0)

    def is_completed(self, iid):
        it = self.items.get(iid)
        if not it:
            return False
        return self.item_price(iid) >= 1500 or ("Boots" in it.get("tags", []) and self.item_price(iid) >= 900)

    def item_vec(self, iid):
        """装备的属性向量（未归一化）+ 特殊标签集合"""
        if iid in self._vec_cache:
            return self._vec_cache[iid]
        it = self.items.get(iid, {})
        st = it.get("stats", {})
        v = {}
        scale = [("FlatPhysicalDamageMod", "AD", 40), ("FlatMagicDamageMod", "AP", 60),
                 ("PercentAttackSpeedMod", "AS", 0.3), ("FlatCritChanceMod", "CRIT", 0.2),
                 ("FlatArmorMod", "ARMOR", 40), ("FlatSpellBlockMod", "MR", 40),
                 ("FlatHPPoolMod", "HP", 350), ("PercentLifeStealMod", "SUSTAIN", 0.1),
                 ("FlatMPPoolMod", "MANA", 400), ("PercentMovementSpeedMod", "MS", 0.05),
                 ("FlatMovementSpeedMod", "MS", 45)]
        for key, dim, s in scale:
            if st.get(key):
                v[dim] = v.get(dim, 0) + min(1.5, st[key] / s)
        tag_dim = {"CooldownReduction": "HASTE", "AbilityHaste": "HASTE", "ArmorPenetration": "LETHAL",
                   "MagicPenetration": "MPEN", "OnHit": "ONHIT", "SpellVamp": "SUSTAIN",
                   "LifeSteal": "SUSTAIN", "Mana": "MANA", "ManaRegen": "MANA", "Health": "HP",
                   "Armor": "ARMOR", "SpellBlock": "MR", "Damage": "AD", "SpellDamage": "AP",
                   "AttackSpeed": "AS", "CriticalStrike": "CRIT", "Tenacity": "TENACITY"}
        for t in it.get("tags", []):
            d = tag_dim.get(t)
            if d and d not in v:
                v[d] = 0.6
        kt = keyword_tags(self.item_desc(iid))
        special = set()
        for d in ("ANTIHEAL", "TENACITY", "SURVIVE", "MAXHP_DMG", "TRUE", "ANTICRIT"):
            if kt.get(d):
                special.add(d)
        if kt.get("HEALSHIELD") and re.search(r"治疗(和|与)护盾|治疗.{0,4}护盾.{0,4}(强度|效果)|(?i:heal (and|&) shield power)",
                                              self.item_desc(iid)):
            v["HEALSHIELD"] = 1.0
        for d in ITEM_ID_TAGS.get(iid, []):
            special.add(d)
        for d in ("MAXHP_DMG", "TRUE"):
            if d in special:
                v[d] = 0.5
        self._vec_cache[iid] = (v, special)
        return v, special

    def candidate_items(self, map_id, allowed=None):
        seen, out = set(), []
        mkey = str(map_id)
        if allowed:  # 有海斗实际装备清单时，以它为准（仍须存在于当前版本的游戏数据）
            for iid in sorted(allowed):
                it = self.items.get(iid)
                if not it or it.get("requiredChampion") or it.get("requiredAlly") or it["name"] in seen:
                    continue
                # 当前版本仍须在海斗商店：可购买、在商店、地图可用
                if not it.get("gold", {}).get("purchasable", True) or it.get("inStore") is False \
                        or (it.get("maps") and not it["maps"].get(mkey, False)):
                    continue
                seen.add(it["name"])
                out.append(iid)
            return out
        for iid, it in self.items.items():
            if iid in IGNORE_ITEMS:
                continue
            g = it.get("gold", {})
            if not g.get("purchasable", True) or it.get("inStore") is False or it.get("hideFromAll"):
                continue
            if it.get("requiredChampion") or it.get("requiredAlly"):
                continue
            # 10 万以上的编号是其他模式的复制品（竞技场 22xxxx、旧装备模式 77xxxx、黄金锅铲 99xxxx…），
            # 只保留编号开头与当前地图相同的模式专属装备（海斗 = 12xxxx）
            if iid >= 100000 and not str(iid).startswith(str(map_id)):
                continue
            maps = it.get("maps", {})
            if maps and not maps.get(mkey, False):
                continue
            # 还能再升级、且升级版在这张地图买得到的，不是成品（鞋子的「升级版」在海斗买不到，所以鞋子保留）
            def sold_here(t):
                u = self.items.get(int(t)) if str(t).isdigit() else None
                return bool(u) and u.get("gold", {}).get("purchasable", True) and u.get("inStore") is not False \
                    and (not u.get("maps") or u["maps"].get(mkey, False))
            if any(sold_here(t) for t in it.get("into", [])):
                continue
            tags = it.get("tags", [])
            if "Consumable" in tags or "Trinket" in tags:
                continue
            is_boot = "Boots" in tags
            if is_boot and g.get("total", 0) < 900:
                continue
            if not is_boot and g.get("total", 0) < 2000:
                continue
            if it["name"] in seen:
                continue
            seen.add(it["name"])
            out.append(iid)
        return out


# 「变成近战」类增幅（例如拔剑吧）：远程专属效果失效、近战装备效果全额（以装备基础编号判断，海斗复制品取后 4 位）
RANGED_ONLY_ITEMS = {3085, 3094}                    # 芮兰飓风箭（分裂箭只有远程有）、冲击火炮（加攻击距离）
MELEE_GOOD_ITEMS = {3074, 3748, 6631, 3071, 3053, 6333, 3078, 6692, 6610, 3181}
MELEE_AUG_RE = re.compile(r"成为近战|变成近战|变为近战|(?i:become[s]? (a )?melee)")


# 描述里没有属性词、但玩法很明确的增幅（多为符文类）
AUG_EXTRA_TAGS = {
    "地狱三头犬": {"AS": 2, "ONHIT": 2, "AD": 1}, "不死魔舞": {"HP": 2, "SUSTAIN": 2, "MS": 1},
    "不可通行": {"ARMOR": 2, "MR": 2, "HP": 1}, "寒霜幽魂": {"HP": 1, "HASTE": 1},
    "顶狙武器": {"AD": 1, "AS": 1, "CRIT": 1}, "幻影武器": {"ONHIT": 2, "HASTE": 1},
    "弹幕神童": {"AD": 1, "AP": 1}, "烈焰折磨": {"HP": 1, "AP": 1}, "堆层暴龙": {"HP": 1},
    "棒棒回力镖": {"AP": 1, "HASTE": 1}, "大地觉醒": {"AP": 1, "MS": 1}, "符文术士": {"AP": 1, "HASTE": 1},
}


def make_aug(name, desc, rarity):
    tags = keyword_tags(name + " " + desc)
    for k, v in AUG_EXTRA_TAGS.get(name, {}).items():
        tags[k] += v
    return {"name": name, "desc": desc, "rarity": rarity, "tags": dict(tags)}


# --------------------------------------------------------------------------------------
# 网上胜率数据（ARAMKit：海克斯大乱斗统计，data.aramkit.com 公开静态文件）
# 只在每局开始时读取你所用英雄的一个统计文件，并按版本缓存，不会高频请求。
# --------------------------------------------------------------------------------------
ARAMKIT = "https://data.aramkit.com"
SEMANTIC_DIM = {
    "abilityPower": "AP", "magicDamage": "AP", "attackDamage": "AD", "physicalDamage": "AD",
    "attackSpeed": "AS", "criticalStrike": "CRIT", "armor": "ARMOR", "magicResist": "MR",
    "health": "HP", "heal": "SUSTAIN", "lifeSteal": "SUSTAIN", "omnivamp": "SUSTAIN",
    "shield": "HEALSHIELD", "movementSpeed": "MS", "onHit": "ONHIT", "mana": "MANA",
    "trueDamage": "TRUE", "armorPenetration": "LETHAL",
}


class StatsProvider:
    def __init__(self, lang="zh_TW", log=print):
        self.lang, self.log = lang, log
        self.dir = os.path.join(APP_DIR, "aramkit")
        os.makedirs(self.dir, exist_ok=True)
        self.version = None          # {"version","dataPath","resourcePath","allMatches",...}
        self.champs = {}             # champion key -> parsed stats
        self.pending = set()
        self.lock = threading.Lock()
        self.on_ready = None
        self.error = ""
        self.item_allow = None       # 海斗商店里买得到的成品装备编号
        self.failed = {}             # 下载失败的英雄 -> 时间（稍后再试）
        self.aug_seen = None         # 实际海斗对局里出现过的增幅编号

    # ---------- 基础 ----------
    def _get(self, path, cache_name, max_age=None):
        cache = os.path.join(self.dir, cache_name)
        if os.path.exists(cache) and (max_age is None or time.time() - os.path.getmtime(cache) < max_age):
            data = read_json(cache)
            if data is not None:          # 缓存坏了就重新下载
                return data
        try:
            data = http_json(f"{ARAMKIT}/{path}", timeout=20)
            write_json(cache, data)
            return data
        except Exception as e:  # noqa
            data = read_json(cache) if os.path.exists(cache) else None   # 断网时用旧缓存
            if data is not None:
                return data
            raise e

    def load_version(self, force=False):
        try:
            v = self._get("data/versions.json", "versions.json", max_age=0 if force else 3600)
            latest = v.get("latest")
            self.version = next((x for x in v.get("versions", []) if x.get("version") == latest),
                                (v.get("versions") or [None])[0])
        except Exception as e:  # noqa
            self.error = tr('无法连接胜率网站（{0}）').format(e)
            self.log(tr("[胜率] ") + self.error)
        return self.version

    game_version = ""
    dataset = "all"          # all＝全部分段；high＝高分段

    def set_dataset(self, ds):
        ds = "high" if ds == "high" else "all"
        if ds == self.dataset:
            return
        with self.lock:
            self.dataset = ds
            self.champs.clear()          # 换分段：重新读取英雄统计
            self.pending.clear()
            self.failed.clear()
        if self.on_ready:
            self.on_ready()

    def label(self):
        if not self.version:
            return ""
        n = self.version.get("highMatches" if self.dataset == "high" else "allMatches", 0)
        tier = tr("高分段") if self.dataset == "high" else tr("全部分段")
        v = self.version.get("version")
        note = tr('，游戏已是 {0}').format(self.game_version) if self.game_version and self.game_version != "cache" \
            and self.game_version != v else ""
        return tr('ARAMKit {0} {1}（{2:.0f}万场{3}）').format(v, tier, n / 1e4, note) if n else f"ARAMKit {v} {tier}"

    def _locs(self):
        """ARAMKit 资源的语言：国服→zh-CN；英文→en-US（取不到退回 zh-TW）；其余（zh_MY/zh_TW）→zh-TW"""
        lg = self.lang.lower().replace("-", "_")
        if lg == "zh_cn":
            return ["zh-CN"]
        if lg.startswith("zh"):
            return ["zh-TW"]
        return ["en-US", "zh-TW"]

    def _res(self, name):
        """读取 ARAMKit 资源文件，回传 (资料, 实际用的语言)"""
        rp = self.version.get("resourcePath", "")
        last = None
        for loc in self._locs():
            short = {"summoner-spells": "ss", "champions": "champs", "items": "items", "augments": "aug"}[name]
            try:
                return self._get(f"{rp}/{loc}/resources/{name}.json", f"{short}_{loc}_{rp.replace('/', '_')}.json"), loc
            except Exception as e:  # noqa
                last = e
        raise last

    # ---------- 召唤师技能名称 ----------
    def load_spell_names(self):
        if not self.version:
            return {}
        try:
            data, loc = self._res("summoner-spells")
            if loc != self._locs()[0]:
                raise ValueError("wrong language")     # 名称语言不对就不用，界面改显示编号
            self.spell_names = {int(k): simp(v.get("name", "")) for k, v in (data or {}).items() if str(k).isdigit()}
        except Exception:  # noqa
            self.spell_names = {}
        return self.spell_names

    spell_names = {}
    balance = {}

    # ---------- 海斗英雄平衡调整（造成/承受伤害、治疗、护盾、韧性…、技能数值改动） ----------
    def load_balance(self):
        if not self.version:
            return {}
        try:
            data, loc = self._res("champions")
        except Exception:  # noqa
            return {}
        same_lang = loc == self._locs()[0]
        out = {}
        for c in (data or {}).values():
            b = c.get("balance") or {}
            mods = {m.get("key"): float(m.get("value") or 0) for m in b.get("modifiers", []) if m.get("key")}
            changes = [(x.get("key", ""), simp(x.get("ability", "")), [simp(l) for l in x.get("lines", [])])
                       for x in b.get("abilityChanges", [])] if same_lang else []
            if c.get("riotId"):
                out[c["riotId"].lower()] = {"mods": mods, "changes": changes}
        self.balance = out
        return out

    def mods(self, cid):
        return (self.balance.get(str(cid).lower()) or {}).get("mods", {})

    # ---------- 海斗实际可用的装备 ----------
    def load_items(self):
        if not self.version and not self.load_version():
            return None
        try:
            data, _loc = self._res("items")
        except Exception as e:  # noqa
            self.log(tr('[胜率] 装备清单下载失败：{0}').format(e))
            return None
        # 只要「商店可买的成品」：排除增幅赠送（黄金锅铲、棱彩装备…）和进化型（魔宗…）
        self.item_allow = {int(k) for k, v in (data or {}).items()
                           if str(k).isdigit() and v.get("purchasable") and v.get("acquisition") == "shop"
                           and v.get("isFinal")}
        return self.item_allow

    # ---------- 增幅中文描述（补齐海斗专属增幅） ----------
    def load_augments(self):
        if not self.version and not self.load_version():
            return []
        try:
            data, loc = self._res("augments")
        except Exception as e:  # noqa
            self.log(tr('[胜率] 增幅描述下载失败：{0}').format(e))
            return []
        other_lang = loc != self._locs()[0]      # 英文取不到、用了中文：只拿属性标注，名称和描述用游戏数据的
        out = []
        for aid, a in (data or {}).items():
            texts, sem = [], Counter()
            for b in (a.get("tooltip") or {}).get("blocks", []):
                for s in b.get("spans", []):
                    if s.get("type") == "text" and s.get("semantic") != "flavorText":
                        texts.append(s.get("text", ""))
                    d = SEMANTIC_DIM.get(s.get("semantic", ""))
                    if d:
                        sem[d] += 1
            rar = {"prismatic": 2, "gold": 1}.get(str(a.get("rarity", "")).lower(), 0)
            aug = make_aug(simp(a.get("name", "")), simp("".join(texts)), rar)
            for k, v in sem.items():
                aug["tags"][k] = aug["tags"].get(k, 0) + min(v, 2)
            aug["id"], aug["aram"] = int(aid), True
            if other_lang:
                aug["desc"], aug["foreign"] = "", True
            out.append(aug)
        self.aug_seen = {a["id"] for a in out}
        return out

    # ---------- 英雄统计（背景下载） ----------
    def get(self, champ_key, light=False):
        """返回已解析的统计；还没有就在背景下载，完成后呼叫 on_ready。
        light=True（选英雄阶段）只下载英雄总表，不下载约 5MB 的「带增幅时的装备胜率」"""
        if not champ_key:
            return None
        with self.lock:
            have = self.champs.get(champ_key)
            if have is not None and (light or not have.get("light")):
                return have
            if champ_key in self.pending or time.time() - self.failed.get(champ_key, 0) < 60:
                return have
            self.pending.add(champ_key)
        threading.Thread(target=self._fetch, args=(champ_key, light), daemon=True).start()
        return have

    def _fetch(self, key, light=False):
        try:
            if not self.version and not self.load_version():
                return
            dp = self.version["dataPath"]
            with self.lock:
                ds = self.dataset
            raw = self._get(f"{dp}/stats/{ds}/champion-details/{key}.json",
                            f"champ_{dp.replace('/', '_')}_{key}.json" if ds == "all" else
                            f"champ_{ds}_{dp.replace('/', '_')}_{key}.json")
            parsed = self._parse(raw)
            if light:
                parsed["by_aug"], parsed["light"] = {}, True
            else:
                parsed["by_aug"] = self._fetch_single_augments(dp, key, ds)
            with self.lock:
                if ds != self.dataset:       # 下载期间换了分段：这份作废
                    return
                self.champs[key] = parsed
                self.failed.pop(key, None)
            if self.on_ready:
                self.on_ready()
        except Exception as e:  # noqa
            self.error = tr('英雄胜率下载失败（{0}）').format(e)
            self.log(tr("[胜率] ") + self.error)
            with self.lock:
                self.failed[key] = time.time()        # 一分钟后再试，不要每秒重试
        finally:
            with self.lock:
                self.pending.discard(key)

    def _fetch_single_augments(self, dp, key, ds="all"):
        """带某个增幅时，这个英雄各装备的胜率（原始文件约 5MB，只保留需要的部分存成小缓存）"""
        cache = os.path.join(self.dir, f"sa_{dp.replace('/', '_')}_{key}.json" if ds == "all" else
                             f"sa_{ds}_{dp.replace('/', '_')}_{key}.json")
        old = read_json(cache) if os.path.exists(cache) else None
        if isinstance(old, dict):
            return {int(k): {int(i): tuple(v) for i, v in d.items()} for k, d in old.items()}
        try:
            raw = http_json(f"{ARAMKIT}/{dp}/stats/{ds}/champion-details/{key}-single-augments.json", timeout=60)
        except Exception as e:  # noqa
            self.log(tr('[胜率] 增幅×装备数据下载失败：{0}').format(e))
            return {}
        out = {}
        for row in raw.get("items", []):
            aid = row.get("augmentId")
            if aid is None:
                continue
            out[int(aid)] = {int(r["id"]): (r.get("calibratedWinRate") or r.get("winRate", 0), r.get("sampleCount", 0))
                             for r in row.get("all", []) if "id" in r and r.get("sampleCount", 0) >= 200}
        write_json(cache, {str(k): {str(i): list(v) for i, v in d.items()} for k, d in out.items()})
        return out

    @staticmethod
    def _parse(raw):
        def rows(lst):
            return {int(r["id"]): {"wr": r.get("calibratedWinRate") or r.get("winRate", 0),
                                   "pick": r.get("pickRate", 0), "n": r.get("sampleCount", 0)}
                    for r in (lst or []) if "id" in r}
        items = raw.get("items", {})
        filt = items.get("filtered") or items.get("unfiltered") or {}
        unf = items.get("unfiltered") or filt
        augs = raw.get("augments", {})
        st = {"wr": raw.get("champion", {}).get("stats", {}).get("winRate", 0.5),
              "n": raw.get("champion", {}).get("stats", {}).get("sampleCount", 0),
              "tier": raw.get("champion", {}).get("tier", ""),
              "items": rows(filt.get("all")),
              "items_any": set(rows(unf.get("all"))),
              "item_slots": {int(k): rows(v) for k, v in (filt.get("slots") or {}).items()},
              "augs": {int(r["id"]): {"wr": r.get("winRate", 0), "pick": r.get("pickRate", 0),
                                      "n": r.get("sampleCount", 0), "tier": r.get("tier", "")}
                       for r in augs.get("all", []) if "id" in r},
              "aug_stages": {int(k): {int(r["id"]): {"wr": r.get("winRate", 0), "pick": r.get("pickRate", 0),
                                                    "n": r.get("sampleCount", 0)} for r in v if "id" in r}
                             for k, v in (augs.get("stages") or {}).items()},
              "core": []}
        # 主流核心出装（胜率最高的前几套）
        b = (raw.get("builds", {}).get("filtered") or {}).get("archetypes", [])
        for arch in b:
            for pf in arch.get("profiles", [])[:3]:
                st["core"].append({"items": [int(x["id"]) for x in pf.get("itemSet", [])],
                                   "wr": pf.get("winRate", 0), "pick": pf.get("pickRate", 0) * arch.get("pickRate", 1)})
        st["core"].sort(key=lambda c: -c["pick"])
        # 出装路线：按购买顺序的三件核心 + 核心之后常见的后续装备 / 鞋子
        st["routes"] = []
        for arch in b:
            for pf in arch.get("profiles", []):
                for rt in pf.get("routes", []):
                    later = {int(x["item"]["id"]): (x.get("calibratedWinRate") or x.get("winRate", 0), x.get("sampleCount", 0))
                             for x in rt.get("laterItems", []) + rt.get("boots", [])
                             if x.get("item", {}).get("id") is not None}
                    st["routes"].append({"order": [int(x["id"]) for x in rt.get("purchaseOrder", [])],
                                         "wr": rt.get("calibratedWinRate") or rt.get("winRate", 0),
                                         "n": rt.get("sampleCount", 0), "later": later})
        st["combos"] = {frozenset(int(i) for i in c.get("augmentIds", [])): (c.get("winRate", 0), c.get("sampleCount", 0))
                        for c in raw.get("augmentCombinations", [])}
        # 技能加点顺序、召唤师技能
        st["skills"] = [(x.get("order", ""), x.get("winRate", 0), x.get("pickRate", 0), x.get("sampleCount", 0))
                        for x in raw.get("skills", []) if x.get("order")]
        st["summoners"] = [([int(y["id"]) for y in x.get("spells", []) if "id" in y], x.get("winRate", 0),
                            x.get("pickRate", 0), x.get("sampleCount", 0)) for x in raw.get("summoners", [])]
        return st


# --------------------------------------------------------------------------------------
# 对局状态
# --------------------------------------------------------------------------------------
class Player:
    def __init__(self, name, cid, items, team, level=1, augments=None):
        self.name, self.cid, self.items, self.team, self.level = name, cid, items, team, level
        self.augments = list(augments or [])
        self.kills = self.deaths = self.assists = self.cs = 0
        self.is_dead, self.respawn = False, 0.0
        self.stats = {}          # 只有自己有：championStats（实际属性）
        self.game_time = 0.0


def mode_kind(mode, map_id):
    """判断模式。海斗有三张地图（咆啸深渊、高辛渡口、屠戮大桥），地图编号不一定都是 12，
    所以同时看游戏模式名称；认不出来的一律按海斗处理（本工具的主要场景）。"""
    m = str(mode or "").upper()
    if m == "CHERRY" or map_id == 30:
        return "arena"
    if any(k in m for k in ("ARAM", "KIWI", "MAYHEM")) or map_id in (12, 14):
        return "aram"
    if m == "CLASSIC" or map_id == 11:
        return "sr"
    return "aram"


ITEM_MAP = {"aram": 12, "arena": 30, "sr": 11}
# 装备推荐权重（契合度 F, 热门度 P, 胜率 W, 本局针对 S），按你已有的大件数：0~1 件 / 2~3 件 / 4 件以上
# 第二个数是本局针对因素的阶段倍数（后期针对更重要）
ITEM_WEIGHTS = [((0.35, 0.30, 0.20, 0.15), 0.75),
                ((0.30, 0.30, 0.20, 0.20), 1.0),
                ((0.25, 0.25, 0.20, 0.30), 1.3)]   # 装备「地图可用」判断用的地图编号


def parse_live(raw):
    """把 allgamedata 解析成 (mode, map_id, me, allies, enemies, gold)"""
    ap = raw.get("activePlayer", {}) or {}

    def ids_of(d):
        """同一个人在不同栏位的各种写法：名字#TAG、名字、召唤师名（统一小写、去空白）"""
        out = set()
        name, tag = d.get("riotIdGameName") or "", d.get("riotIdTagLine") or ""
        for v in (d.get("riotId"), d.get("summonerName"), name, f"{name}#{tag}" if name and tag else None):
            if v:
                v = str(v).strip().lower()
                out.add(v)
                out.add(v.split("#")[0])
        return out - {""}
    my_ids = ids_of(ap)
    gd = raw.get("gameData", {}) or {}
    mode, map_id = gd.get("gameMode", "?"), gd.get("mapNumber", 12)
    players = []
    for p in raw.get("allPlayers", []):
        # rawChampionName 有两种写法：game_character_displayname_Aatrox / Character_Aatrox_Name
        cid = re.sub(r"(?i)^(game_character_displayname_|character_)|_name$", "", p.get("rawChampionName") or "")
        if not cid:
            cid = p.get("championName", "?")
        items = [it.get("itemID") for it in p.get("items", []) if it.get("itemID") not in IGNORE_ITEMS]
        augs = []
        for k, v in p.items():
            if "augment" in k.lower() and isinstance(v, list):
                for a in v:
                    augs.append(a.get("displayName") or a.get("name") if isinstance(a, dict) else str(a))
        team = p.get("subteamId") or p.get("subteam") or p.get("team")
        name = p.get("riotId") or p.get("summonerName") or cid
        pl = Player(name, cid, items, team, p.get("level", 1), [a for a in augs if a])
        pl.ids = ids_of(p)
        sc = p.get("scores", {}) or {}
        pl.kills, pl.deaths = sc.get("kills", 0), sc.get("deaths", 0)
        pl.assists, pl.cs = sc.get("assists", 0), sc.get("creepScore", 0)
        pl.is_dead, pl.respawn = bool(p.get("isDead")), float(p.get("respawnTimer", 0) or 0)
        players.append(pl)
    full = {i for i in my_ids if "#" in i}
    me = next((p for p in players if full and p.ids & full), None) or \
        next((p for p in players if p.ids & my_ids), None)
    if me is None and players:
        # 名字对不上：用你技能的内部编号认英雄（例如 Q 的编号 YasuoQ1Wrapper 以英雄名开头）
        ab = ap.get("abilities") or {}
        sid = str((ab.get("Q") or {}).get("id") or (ab.get("Passive") or {}).get("id") or "").lower()
        hits = [p for p in players if p.cid and sid.startswith(p.cid.lower())]
        me = max(hits, key=lambda p: len(p.cid)) if hits else players[0]
    if me is None:
        return mode, map_id, None, [], [], 0
    me.stats = ap.get("championStats", {}) or {}
    me.game_time = float(gd.get("gameTime", 0) or 0)
    for k, v in ap.items():  # 某些版本/模式可能把自己的增幅放在 activePlayer 里
        if "augment" in k.lower() and isinstance(v, list):
            for a in v:
                n = a.get("displayName") or a.get("name") if isinstance(a, dict) else str(a)
                if n and n not in me.augments:
                    me.augments.append(n)
    allies = [p for p in players if p is not me and p.team == me.team]
    enemies = [p for p in players if p is not me and p.team != me.team]
    return mode, map_id, me, allies, enemies, int(ap.get("currentGold", 0) or 0)


# --------------------------------------------------------------------------------------
# 推荐引擎
# --------------------------------------------------------------------------------------
class Advisor:
    def __init__(self, gd, stats=None):
        self.gd = gd
        self.stats = stats
        self.all_index = {a["name"]: a for a in gd.augments}
        for a in gd.augments:  # 别名（网站上的旧译名）也能对应到同一个增幅
            for al in a.get("aliases", []):
                self.all_index.setdefault(al, a)
        self.aug_index = self.all_index
        self.pool_mode = None

    def set_mode(self, kind):
        """海克斯大乱斗只用海斗增幅池；斗魂竞技场用其余的"""
        mode = "aram" if kind == "aram" else "arena"
        if mode == self.pool_mode:
            return
        self.pool_mode = mode
        seen = self.stats.aug_seen if (self.stats and self.stats.aug_seen and mode == "aram") else None
        if seen:  # 以实际海斗对局里出现过的增幅为准（停用的不推荐，但屏幕识别仍能认出）
            cur = getattr(self.gd, "current_aug_ids", None) or seen   # 当前版本仍存在的
            pool = {n: a for n, a in self.all_index.items()
                    if a.get("id") in seen and a.get("id") in cur and n == a["name"]}
        else:
            pool = {n: a for n, a in self.all_index.items() if bool(a.get("aram")) == (mode == "aram")}
        self.aug_index = pool if len(pool) >= 20 else self.all_index

    # ---------- augments lookup ----------
    def find_aug(self, text):
        text = text.strip()
        if not text:
            return None
        if text in self.aug_index:
            return self.aug_index[text]
        hits = [a for n, a in self.aug_index.items() if len(n) >= 2 and (text in n or n in text)]
        if hits:
            return min(hits, key=lambda a: abs(len(a["name"]) - len(text)))
        m = self.match_name(text)
        return m or make_aug(text, "", 0)  # 未知增幅：仅按名字关键词判断

    def match_name(self, text, cutoff=0.6):
        """OCR 容错匹配：先在当前模式的增幅池找，找不到再到全部增幅找（要求更像）"""
        import difflib

        def norm(x):
            return re.sub(r"[\s'\-!.,:]", "", x).lower()
        nt = norm(text)
        for idx in (self.aug_index, self.all_index):     # 英文 OCR 常丢空格/大小写不一：先比规整后的名字
            for n, a in idx.items():
                if norm(n) == nt and nt:
                    return a
        best = difflib.get_close_matches(text, list(self.aug_index), n=1, cutoff=cutoff)
        if best:
            return self.aug_index[best[0]]
        best = difflib.get_close_matches(text, list(self.all_index), n=1, cutoff=max(cutoff, 0.8))
        return self.all_index[best[0]] if best else None

    # ---------- 网上胜率 ----------
    def champ_stats(self, cid):
        if not self.stats:
            return None
        c = self.gd.champ(cid)
        return self.stats.get(c.get("key")) if c else None

    @staticmethod
    def _wmean(rows):
        """按样本量加权的平均胜率"""
        tot = sum(r["n"] for r in rows.values())
        return sum(r["wr"] * r["n"] for r in rows.values()) / tot if tot else None

    @staticmethod
    def _shrink(diff, n, k):
        """小样本收缩：样本越少越不可信（几百场的 +3% 多半是噪声，或是本来就领先才出的）"""
        return diff * n / (n + k)

    def item_stat_factor(self, iid, cs, nslot, owned_core=(), my_aug_ids=()):
        """这件装在「这个英雄 + 第几件 + 已选增幅 + 已出路线」下的网上数据。
        回传 {"lift": 收缩后的胜率差, "raw": 实际胜率差, "text": 说明, "wr": 显示用胜率, "pop": 热门度}；没有数据回传 None。
        胜率差都是和「同一条件下的平均」比（同一件数 / 同一增幅 / 同样已出核心时的其他选择），
        再按样本量收缩：lift = (胜率 − 平均) × n / (n + K)。"""
        if not cs:
            return None
        cache = cs.setdefault("_base", {})
        parts = []   # (收缩后的胜率差, 实际胜率差, 说明, 胜率)
        # 1) 第几件时出它（ARAMKit 的第几件包含鞋子）：和这一件的平均比
        tbl = cs["item_slots"].get(nslot) or {}
        slot = tbl.get(iid)
        over = cs["items"].get(iid)
        if ("slot", nslot) not in cache:
            cache[("slot", nslot)] = self._wmean(tbl)
        if "all" not in cache:
            cache["all"] = self._wmean(cs["items"])
        if slot and slot["n"] >= 300 and cache[("slot", nslot)]:
            r, base = slot, cache[("slot", nslot)]
        elif over and over["n"] >= 300 and cache["all"]:
            r, base = over, cache["all"]
        else:
            r, base = None, None
        if r:
            parts.append((self._shrink(r["wr"] - base, r["n"], 20000), r["wr"] - base,
                          tr('网上胜率 {0:.1f}%').format(r['wr'] * 100), r["wr"]))
        # 2) 你已选的增幅：带这个增幅时出这件的胜率，对比带这个增幅时所有装备的平均
        for aid in my_aug_ids:
            table = cs.get("by_aug", {}).get(aid, {})
            row = table.get(iid)
            bases = cs.setdefault("_aug_item_base", {})
            if aid not in bases and table:
                tot = sum(n for _, n in table.values())
                bases[aid] = sum(w * n for w, n in table.values()) / tot if tot else None
            aug_base = bases.get(aid)
            if row and aug_base and row[1] >= 300:
                name = self.aug_name_by_id(aid)
                parts.append((self._shrink(row[0] - aug_base, row[1], 3000), row[0] - aug_base,
                              tr('带「{0}」时胜率 {1:.1f}%').format(name, row[0] * 100), row[0]))
        # 3) 出装路线：和你已出核心相符的路线里，「下一件是它」的对比「这些路线的平均」；
        #    三件核心都齐了：核心后的常见后续，对比这条路线本身
        routes = cs.get("routes", [])
        owned = set(owned_core)
        match = [rt for rt in routes if rt["order"] and owned.issubset(rt["order"]) and len(owned) < len(rt["order"])]
        mtot = sum(rt["n"] for rt in match)
        nxt = [rt for rt in match if next((i for i in rt["order"] if i not in owned), None) == iid]
        nxt_n = sum(rt["n"] for rt in nxt)
        later = None
        for rt in routes:
            if rt["order"] and set(rt["order"]).issubset(owned) and iid in rt["later"]:
                wr, n = rt["later"][iid]
                if n >= 300 and (later is None or n > later[2]):
                    later = (wr - rt["wr"], wr, n)
        if nxt_n >= 500 and mtot:
            wr = sum(rt["wr"] * rt["n"] for rt in nxt) / nxt_n
            mbase = sum(rt["wr"] * rt["n"] for rt in match) / mtot
            parts.append((self._shrink(wr - mbase, nxt_n, 20000), wr - mbase,
                          tr('{0}，胜率 {1:.1f}%').format(tr("主流路线的下一件"), wr * 100), wr))
        elif later:
            parts.append((self._shrink(later[0], later[2], 5000), later[0],
                          tr('{0}，胜率 {1:.1f}%').format(tr("你这套核心后的常见选择"), later[1] * 100), later[1]))
        # 热门度：这一件时的购买占比 / 整局购买率的一半 / 相符路线里下一件是它的比例，取最高
        pop = max(slot["pick"] if slot else 0.0, 0.5 * over["pick"] if over else 0.0,
                  nxt_n / mtot if mtot else 0.0)
        if not parts:
            return {"lift": 0.0, "raw": 0.0, "text": tr("这个英雄在海斗几乎没人出") if pop < 0.005 else "",
                    "wr": None, "pop": pop}
        lift = sum(x[0] for x in parts) / len(parts)
        main = max(parts, key=lambda x: abs(x[0]))
        return {"lift": lift, "raw": main[1], "wr": main[3], "pop": pop,
                "text": tr('{0}（比平均{1:+.1f}%）').format(main[2], main[1] * 100)}

    def bal(self, cid, key):
        """海斗平衡调整（例如 damageDealt -0.1 表示造成伤害 -10%）"""
        return self.stats.mods(cid).get(key, 0.0) if self.stats else 0.0

    def gd_item_names(self):
        if not hasattr(self, "_item_names"):
            self._item_names = {it.get("name") for it in self.gd.items.values()}
        return self._item_names

    def aug_name_by_id(self, aid):
        for a in self.all_index.values():
            if a.get("id") == aid:
                return a["name"]
        return str(aid)

    @staticmethod
    def aug_stat_factor(a, cs, stage, my_aug_ids=()):
        """这个增幅在「这个英雄 + 第几次选」下的胜率；若和你已选的增幅有组合数据，一并算入"""
        aid = a.get("id")
        if not cs or not aid:
            return None
        r = cs["aug_stages"].get(stage, {}).get(aid)
        if not r or r["n"] < 500:
            r = cs["augs"].get(aid)
        if not r or r["n"] < 500:
            return None
        raw_lift = r["wr"] - cs["wr"]
        lift = Advisor._shrink(raw_lift, r["n"], 5000)         # 小样本收缩
        text, shown = tr('网上胜率 {0:.1f}%').format(r['wr'] * 100), r["wr"]
        for m in my_aug_ids:
            combo = cs.get("combos", {}).get(frozenset((m, aid)))
            m_base = cs["augs"].get(m, {}).get("wr")
            if combo and m_base and combo[1] >= 500:
                clift = combo[0] - m_base          # 已有 m 的情况下再拿它，比只有 m 高多少
                lift = (lift + 2 * Advisor._shrink(clift, combo[1], 3000)) / 3
                raw_lift = clift
                text, shown = tr('和已选增幅组合胜率 {0:.1f}%').format(combo[0] * 100), combo[0]
                break
        return (max(-0.45, min(0.45, lift * 9)), tr('{0}（比平均{1:+.1f}%）').format(text, raw_lift * 100), shown)

    def resolve_seen(self, name, desc):
        """屏幕识别到的增幅：优先用库里的数据，库里没有就用识别到的描述打分"""
        a = self.aug_index.get(name) or self.match_name(name, 0.7)
        if a and a.get("desc"):
            return a
        # 库里没有描述 → 用屏幕上读到的描述打分（保留编号以便查胜率）
        m = make_aug(a["name"] if a else name, desc, a.get("rarity", 0) if a else 0)
        if a and a.get("id"):
            m["id"] = a["id"]
        return m

    # ---------- profiles ----------
    def champ_profile(self, cid):
        if cid in CHAMP_OVERRIDE:
            return norm(dict(CHAMP_OVERRIDE[cid]))
        c = self.gd.champ(cid)
        if not c:
            return norm({"AD": .6, "AP": .6, "HP": .4, "HASTE": .4})
        info = c.get("info", {})
        magic_based = info.get("magic", 0) > info.get("attack", 0) + 1
        v = {}
        for i, tag in enumerate(c.get("tags", [])[:2]):
            base = dict(ROLE_BASE.get(tag, {}))
            if magic_based and tag in ("Assassin", "Fighter", "Marksman"):
                if "AD" in base:
                    base["AP"] = base.pop("AD")
                if "LETHAL" in base:
                    base["MPEN"] = base.pop("LETHAL")
                base.pop("CRIT", None)
            add_into(v, base, 1.0 if i == 0 else 0.55)
        return norm(v)

    def items_profile(self, items):
        v = {}
        for iid in items:
            if self.gd.is_completed(iid) and not self.gd.is_boots(iid):
                add_into(v, self.gd.item_vec(iid)[0])
        return norm(v)

    def my_profile(self, me, my_augs):
        base = self.champ_profile(me.cid)
        owned = self.items_profile(me.items)
        prof = {}
        add_into(prof, base, 0.55 if owned else 1.0)
        add_into(prof, owned, 0.45)
        for a in my_augs:
            add_into(prof, {k: v for k, v in norm(a["tags"]).items() if k in BUILD_DIMS}, 0.2)
        return norm(prof)

    # ---------- 战局 ----------
    def power(self, p):
        """用装备价值 + 击杀/助攻/死亡 + 等级估算一个人的强度（金币当量）"""
        val = sum(self.gd.item_price(i) for i in p.items)
        return max(300, val + 250 * p.kills + 120 * p.assists - 150 * p.deaths + 180 * p.level)

    def dmg_split(self, p):
        """估算一名玩家的 物理/魔法 伤害比例（英雄基底 + 装备）"""
        c = self.gd.champ(p.cid) or {}
        info = c.get("info", {"attack": 5, "magic": 5})
        ad = info.get("attack", 5) + 0.1
        ap = info.get("magic", 5) + 0.1
        if p.cid in CHAMP_OVERRIDE:
            o = CHAMP_OVERRIDE[p.cid]
            ad, ap = 1 + 9 * o.get("AD", 0), 1 + 9 * o.get("AP", 0)
        for iid in p.items:
            st = self.gd.items.get(iid, {}).get("stats", {})
            ad += st.get("FlatPhysicalDamageMod", 0) / 12 + st.get("FlatCritChanceMod", 0) * 15
            ap += st.get("FlatMagicDamageMod", 0) / 15
        return ad / (ad + ap)

    def role_of(self, p, prof=None):
        prof = prof or self.champ_profile(p.cid)
        tags = (self.gd.champ(p.cid) or {}).get("tags", [])
        front = prof.get("HP", 0) + prof.get("ARMOR", 0) + prof.get("MR", 0)
        if front > 0.75 or tags[:1] == ["Tank"]:
            return "tank"
        if prof.get("HEALSHIELD", 0) > 0.35 or champ_role(self.gd, p.cid, "enchanter"):
            return "support"
        if tags[:1] == ["Assassin"]:
            return "assassin"
        if prof.get("AS", 0) + prof.get("CRIT", 0) > 0.6 or tags[:1] == ["Marksman"]:
            return "adc"
        if prof.get("AP", 0) > prof.get("AD", 0):
            return "mage"
        return "fighter"

    def team_threat(self, enemies, enemy_augs, allies, ally_augs, me):
        gd = self.gd
        t = {"heal": 0.0, "healers": [], "armor": 0.0, "mr": 0.0, "hp": 0.0, "tanks": [], "cc": [],
             "burst": [], "crit_items": 0, "as_items": 0, "n": max(1, len(enemies))}
        # 敌方强度 × 海斗平衡（造成伤害被削弱的英雄威胁较小）
        pw = {id(e): self.power(e) * (1 + self.bal(e.cid, "damageDealt")) for e in enemies}
        avg = sum(pw.values()) / max(1, len(pw)) if pw else 1
        adw = apw = 0.0
        for e in enemies:
            c = gd.champ(e.cid) or {}
            info = c.get("info", {})
            tags = c.get("tags", [])
            w = pw[id(e)] / avg            # 越肥的敌人权重越高
            if "Tank" in tags and "Support" in tags:
                w *= 0.6
            share = self.dmg_split(e)
            adw += share * w
            apw += (1 - share) * w
            for iid in e.items:
                st = gd.items.get(iid, {}).get("stats", {})
                t["armor"] += st.get("FlatArmorMod", 0)
                t["mr"] += st.get("FlatSpellBlockMod", 0)
                t["hp"] += st.get("FlatHPPoolMod", 0)
                if st.get("FlatCritChanceMod"):
                    t["crit_items"] += 1
                if st.get("PercentAttackSpeedMod"):
                    t["as_items"] += 1
                it_tags = gd.items.get(iid, {}).get("tags", [])
                if "LifeSteal" in it_tags or "SpellVamp" in it_tags:
                    t["heal"] += 0.4
            nm = gd.champ_name(e.cid)
            if champ_role(gd, e.cid, "heal"):
                t["heal"] += 1.0 * (1 + self.bal(e.cid, "healing")) * (1 + 0.5 * self.bal(e.cid, "shielding"))
                t["healers"].append(nm)
            if "Tank" in tags or (tags[:1] == ["Fighter"] and info.get("defense", 0) >= 7):
                t["tanks"].append(nm)
            if champ_role(gd, e.cid, "cc"):
                t["cc"].append(nm)
            if "Assassin" in tags or e.cid in BURST_MAGES:
                t["burst"].append(nm)
        for a in enemy_augs:
            tg = a["tags"]
            if tg.get("SUSTAIN") or tg.get("HEALSHIELD"):
                t["heal"] += 0.5
                t["healers"].append(tr("「") + a["name"] + tr("」"))
            if tg.get("ARMOR"):
                t["armor"] += 20
            if tg.get("MR"):
                t["mr"] += 20
            if tg.get("HP"):
                t["hp"] += 300
        t["ad_share"] = adw / ((adw + apw) or 1)
        # 最大威胁（敌方核心）
        if enemies:
            carry = max(enemies, key=lambda e: pw[id(e)] * (0.6 if "Tank" in (gd.champ(e.cid) or {}).get("tags", [])
                                                           else 1.0))
            t["carry"] = carry
            t["carry_name"] = gd.champ_name(carry.cid)
            t["carry_ad"] = self.dmg_split(carry) > 0.5
            t["carry_ratio"] = pw[id(carry)] / avg
            t["carry_crit"] = sum(1 for i in carry.items if gd.items.get(i, {}).get("stats", {}).get("FlatCritChanceMod"))
        else:
            t["carry"], t["carry_name"], t["carry_ad"], t["carry_ratio"], t["carry_crit"] = None, "", True, 1, 0
        # 双方实力
        t["enemy_power"] = sum(pw.values())
        t["ally_power"] = sum(self.power(p) for p in allies + [me])
        t["power_diff"] = t["ally_power"] - t["enemy_power"] * (len(allies) + 1) / max(1, len(enemies))
        t["kills_ally"] = sum(p.kills for p in allies + [me])
        t["kills_enemy"] = sum(p.kills for p in enemies)
        # 我方
        t["team_antiheal"] = sum(1 for p in allies + [me] for iid in p.items
                                 if "ANTIHEAL" in gd.item_vec(iid)[1])
        t["team_antiheal"] += sum(1 for a in ally_augs if a["tags"].get("ANTIHEAL"))
        t["me_antiheal"] = any("ANTIHEAL" in gd.item_vec(i)[1] for i in me.items)
        t["enemy_antiheal"] = sum(1 for e in enemies for i in e.items if "ANTIHEAL" in gd.item_vec(i)[1]) + \
            sum(1 for a in enemy_augs if a["tags"].get("ANTIHEAL"))
        t["ally_tanks"] = [gd.champ_name(p.cid) for p in allies
                           if "Tank" in (gd.champ(p.cid) or {}).get("tags", [])]
        t["ally_enchanters"] = [gd.champ_name(p.cid) for p in allies if champ_role(gd, p.cid, "enchanter")]
        ally_ap = sum(1 for p in allies + [me] if self.dmg_split(p) < 0.5)
        t["ally_ap_share"] = ally_ap / (len(allies) + 1)
        t["ally_engage"] = [gd.champ_name(p.cid) for p in allies + [me] if champ_role(gd, p.cid, "engage")]
        t["enemy_engage"] = [gd.champ_name(p.cid) for p in enemies if champ_role(gd, p.cid, "engage")]
        t["ally_poke"] = [gd.champ_name(p.cid) for p in allies + [me] if champ_role(gd, p.cid, "poke")]
        t["enemy_poke"] = [gd.champ_name(p.cid) for p in enemies if champ_role(gd, p.cid, "poke")]
        t["enemy_augs"] = enemy_augs
        t["ally_augs"] = ally_augs
        return t

    # ---------- 共用：克制因子 ----------
    def counter_factors(self, vec, special, t, prof, kind="item", ehp_done=False, phase=1.0):
        f = []
        n = t["n"]
        heal = t["heal"]
        carry = t.get("carry_name", "")
        if "ANTIHEAL" in special or vec.get("ANTIHEAL"):
            if t["me_antiheal"]:
                f.append((-0.3, tr("你已有重伤装，重复收益低")))
            elif heal >= 1.2:
                w = min(heal / 3, 1.3) * (0.5 if t["team_antiheal"] else 1.0)
                who = tr("、").join(t["healers"][:3])
                f.append((0.32 * w * phase, tr('敌方回复强（{0}）').format(who) + (tr("，队友重伤不够") if t["team_antiheal"] else tr("，急需重伤"))))
        if not ehp_done:
            def_scale = 1.0 if (prof.get("HP", 0) + prof.get("ARMOR", 0) + prof.get("MR", 0)) > 0.3 else 0.6
            if vec.get("ARMOR") and t["ad_share"] > 0.55:
                f.append((0.35 * (t["ad_share"] - 0.5) * 2 * min(vec["ARMOR"], 1) * def_scale,
                          tr('敌方物理伤害占{0}%').format(round(t['ad_share'] * 100))))
            if vec.get("MR") and t["ad_share"] < 0.45:
                f.append((0.35 * (0.5 - t["ad_share"]) * 2 * min(vec["MR"], 1) * def_scale,
                          tr('敌方魔法伤害占{0}%').format(round((1 - t['ad_share']) * 100))))
        arm_avg, mr_avg = t["armor"] / n, t["mr"] / n
        if vec.get("LETHAL") and arm_avg > 40 and prof.get("AD", 0) > 0.3:
            f.append((min(0.3, arm_avg / 400) * phase, tr('敌方人均已堆{0}物理防御，穿甲收益高').format(round(arm_avg))))
        if vec.get("MPEN") and mr_avg > 35 and prof.get("AP", 0) > 0.3:
            f.append((min(0.3, mr_avg / 350) * phase, tr('敌方人均已堆{0}魔法防御，魔穿收益高').format(round(mr_avg))))
        if ("MAXHP_DMG" in special or vec.get("MAXHP_DMG") or vec.get("TRUE")) and \
                (len(t["tanks"]) >= 2 or t["hp"] / n > 700):
            f.append(((0.12 + 0.06 * len(t["tanks"])) * phase,
                      tr('敌方前排厚（{0}）').format(tr('、').join(t['tanks'][:3]) or tr('生命装多'))))
        if ("TENACITY" in special or vec.get("TENACITY")) and len(t["cc"]) >= 2:
            f.append((0.08 * len(t["cc"]) * phase, tr('敌方控制多（{0}）').format(tr('、').join(t['cc'][:3]))))
        if ("SURVIVE" in special or vec.get("SURVIVE")) and len(t["burst"]) >= 1:
            fed = carry in t["burst"] and t.get("carry_ratio", 1) > 1.3
            f.append(((0.09 * len(t["burst"]) + 0.05 + (0.1 if fed else 0)) * phase,
                      tr('{0}已经打肥，爆发打得死你').format(carry) if fed else tr('敌方爆发高（{0}）').format(tr('、').join(t['burst'][:3]))))
        if ("ANTICRIT" in special or vec.get("ANTICRIT")) and t["crit_items"] >= 2:
            fed = t.get("carry_crit", 0) >= 2 and t.get("carry_ad")
            f.append(((0.08 * t["crit_items"] + (0.08 if fed else 0)) * phase,
                      tr('克制{0}的暴击（{1}件）').format(carry, t['carry_crit']) if fed else tr('敌方已有{0}件暴击装').format(t['crit_items'])))
        if ("ANTIAS" in special) and t["as_items"] >= 3:
            f.append((0.05 * t["as_items"] * phase, tr('敌方攻速装多（{0}件）').format(t['as_items'])))
        if (vec.get("SUSTAIN") or vec.get("HEALSHIELD")) and t.get("enemy_antiheal", 0) >= 2:
            f.append((-0.06 * min(t["enemy_antiheal"], 4), tr('敌方已有 {0} 个重伤来源，回复效果打折').format(t['enemy_antiheal'])))
        frontline = prof.get("HP", 0) + prof.get("ARMOR", 0) + prof.get("MR", 0)
        if not t["ally_tanks"] and frontline > 0.45 and (vec.get("HP") or vec.get("ARMOR")):
            f.append((0.1, tr("队伍缺前排，你需要更肉")))
        if t["ally_enchanters"] and (vec.get("AS") or vec.get("CRIT")) and prof.get("AS", 0) > 0.3:
            f.append((0.06, tr('有{0}保护，可放心堆输出').format(t['ally_enchanters'][0])))
        if vec.get("AP") and t["ally_ap_share"] < 0.25 and prof.get("AP", 0) > 0.3:
            f.append((0.05, tr("队伍缺魔法伤害，你的魔攻很关键")))
        return f

    def ehp_factor(self, iid, me, t, prof, role):
        """依你目前的实际物理/魔法防御与生命，计算这件装对敌方伤害组成的有效生命增幅"""
        s = me.stats or {}
        if not s:
            return None
        st = self.gd.items.get(iid, {}).get("stats", {})
        da, dm, dh = st.get("FlatArmorMod", 0), st.get("FlatSpellBlockMod", 0), st.get("FlatHPPoolMod", 0)
        if not (da or dm or dh):
            return None
        armor = max(0.0, s.get("armor", 40))
        mr = max(0.0, s.get("magicResist", 35))
        hp = max(400.0, s.get("maxHealth", 1500))
        ad = t["ad_share"]
        gain = ad * ((1 + dh / hp) * (1 + da / (100 + armor)) - 1) + \
            (1 - ad) * ((1 + dh / hp) * (1 + dm / (100 + mr)) - 1)
        need = {"tank": 1.25, "fighter": 1.0, "support": 0.8, "mage": 0.7, "assassin": 0.6, "adc": 0.6}[role]
        need *= 1 + 2 * self.bal(me.cid, "damageTaken")       # 海斗里你承受伤害增加 → 防御更值
        if t["power_diff"] < -1500:
            need *= 1.25
        val = min(0.4, gain * 0.95 * need)
        kind = tr("物理") if ad >= 0.55 else tr("魔法") if ad <= 0.45 else tr("混合")
        who = tr('{0}等').format(t['carry_name']) if t.get("carry_name") else tr("敌方")
        return (val, tr('对{0}{1}伤害有效生命 +{2}%').format(who, kind, round(gain * 100)))

    def buy_hint(self, iid, gold, owned):
        gd = self.gd
        it = gd.items.get(iid, {})
        total = gd.item_price(iid)
        comps = [int(c) for c in it.get("from", []) if str(c).isdigit()]
        have = [c for c in comps if c in owned]
        remain = total - sum(gd.item_price(c) for c in have)
        if gold >= remain:
            return tr("可直接买")
        todo = [c for c in comps if c not in have]
        # 下一步能买的最贵零件（包含零件的零件）
        pool, seen = list(todo), set()
        while pool:
            c = pool.pop()
            if c in seen:
                continue
            seen.add(c)
            pool += [int(x) for x in gd.items.get(c, {}).get("from", []) if str(x).isdigit()]
        afford = [c for c in seen if gd.item_price(c) <= gold and c not in owned]
        if afford:
            c = max(afford, key=gd.item_price)
            return tr('先买{0}').format(gd.item_name(c))
        return tr('差{0}g').format(int(math.ceil(remain - gold)))

    @staticmethod
    def top_dims(prof, vec, k=2):
        both = sorted(((prof.get(d, 0) * vec.get(d, 0), d) for d in vec if d in DIM_LABEL), reverse=True)
        return [tr(DIM_LABEL[d]) for s, d in both[:k] if s > 0.02]

    @staticmethod
    def to_score(raw):
        return max(1, min(99, int(round(100 * (1 - math.exp(-2.1 * max(raw, 0)))))))

    @staticmethod
    def reason(fit_text, factors):
        pos = sorted([f for f in factors if f[0] > 0], reverse=True)
        neg = [f for f in factors if f[0] < 0]
        strong = [txt for v, txt in pos if v >= 0.08]
        weak = [txt for v, txt in pos if v < 0.08]
        parts = strong[:1] + ([fit_text] if fit_text else []) + strong[1:2]
        if len(parts) < 2 and weak and (not strong or not fit_text):
            parts += weak[:1]
        parts = parts[:2]
        if neg:
            parts = [neg[0][1]] + parts[:1]
        return tr("，").join(parts) + tr("。") if parts else tr("属性契合。")

    # ---------- items ----------
    def recommend_items(self, me, allies, enemies, my_augs, t, map_id, gold=0, k=5, cs=None):
        gd = self.gd
        prof = self.my_profile(me, my_augs)
        role = self.role_of(me, prof)
        owned_names = {gd.item_name(i) for i in me.items}
        legend = sum(1 for i in me.items if gd.is_completed(i) and not gd.is_boots(i))
        owned_core = [i for i in me.items if gd.is_completed(i) and not gd.is_boots(i)]
        # ARAMKit 的「第几件」包含二级鞋
        nslot = 1 + legend + sum(1 for i in me.items if gd.is_boots(i) and gd.item_price(i) >= 900)
        my_aug_ids = [a["id"] for a in my_augs if a.get("id")]
        # 阶段权重（契合度 F / 热门度 P / 胜率 W / 本局针对 S）：前期看核心，后期看针对
        wts, phase = ITEM_WEIGHTS[0 if legend <= 1 else 1 if legend <= 3 else 2]
        s = me.stats or {}
        # 选了「变成近战」的增幅、而你本来是远程英雄：装备的取舍跟着变
        ranged = float(((gd.champ(me.cid) or {}).get("stats") or {}).get("attackrange", 0) or 0) >= 300
        melee_aug = next((a["name"] for a in my_augs if MELEE_AUG_RE.search(a.get("desc", ""))), None) if ranged else None
        out = []
        allowed = self.stats.item_allow if self.stats else None   # 海斗实际商店清单
        for iid in gd.candidate_items(map_id, allowed):
            if gd.item_name(iid) in owned_names:
                continue
            if gd.is_boots(iid):
                continue                     # 鞋子另外单独推荐（见 recommend_boots）
            vec, special = gd.item_vec(iid)
            nv = norm({d: vec[d] for d in vec if d in BUILD_DIMS})
            fit = cosine(prof, nv)
            base_id = iid % 10000 if iid >= 100000 else iid
            if fit < (0.25 if melee_aug and base_id in MELEE_GOOD_ITEMS else 0.35):
                continue
            ehp = self.ehp_factor(iid, me, t, prof, role)
            factors = self.counter_factors(vec, special, t, prof, ehp_done=ehp is not None, phase=phase)
            if ehp and ehp[0] > 0.04:
                factors.append(ehp)
            st = gd.items.get(iid, {}).get("stats", {})
            if st.get("FlatCritChanceMod") and s.get("critChance", 0) >= 0.95:
                factors.append((-0.3, tr("你的暴击已满，暴击属性浪费")))
            if st.get("PercentAttackSpeedMod") and s.get("attackSpeed", 0) >= 2.3:
                factors.append((-0.15, tr("攻速已接近上限")))
            if melee_aug and base_id in RANGED_ONLY_ITEMS:
                factors.append((-0.35, tr("「{0}」让你变近战，这件的远程效果用不上").format(melee_aug)))
            elif melee_aug and base_id in MELEE_GOOD_ITEMS:
                factors.append((0.12, tr("「{0}」让你变近战，近战效果全额").format(melee_aug)))
            syn = [a["name"] for a in my_augs if cosine(norm(a["tags"]), nv) > 0.5]
            if syn:
                factors.append((0.08, tr('与增幅「{0}」联动').format(syn[0])))
            sf = self.item_stat_factor(iid, cs, nslot, owned_core, my_aug_ids)
            if melee_aug and base_id in MELEE_GOOD_ITEMS and sf is not None and sf["pop"] < 0.05:
                sf = None           # 远程时的出装数据不适用（平时没人出近战装）：热门度 / 胜率改用中性值
            dmg_item = vec.get("AD", 0) + vec.get("AP", 0) + vec.get("CRIT", 0) > 0.8
            if t["power_diff"] > 2000 and dmg_item and role not in ("tank", "support"):
                factors.append((0.05, tr("我方领先，堆伤害滚雪球")))
            if t["power_diff"] < -2000 and ("SURVIVE" in special or (ehp and ehp[0] > 0.1)):
                factors.append((0.06, tr("我方落后，先保命再反打")))
            raw, parts_txt = self.item_formula(fit, sf, factors, wts)
            dbf = self.db_factor(me, "items", iid, 0.08)
            if dbf:                         # 自建数据库：±最多 0.08
                raw += dbf[0]
                parts_txt += " {0:+.2f}D".format(dbf[0])
                factors = factors + [dbf]
            hab = self.habit_item(me, iid)
            if hab:                         # 你的习惯：+最多 0.10（熟悉而且赢得多的更多）
                raw += hab[0]
                parts_txt += " + U{0:.2f}".format(hab[0])
                factors = factors + [hab]
            dims = self.top_dims(prof, nv)
            fit_text = tr('契合你的{0}路线').format('/'.join(dims)) if dims else ""
            rf = [f for f in factors if f[0] > 0 or f[0] <= -0.05]
            if sf and sf["text"] and (abs(sf["raw"]) >= 0.01 or sf["pop"] < 0.005):
                rf.append((0.1 if sf["raw"] > 0 else -0.1, sf["text"]))
            out.append({"name": gd.item_name(iid), "id": iid, "score": self.item_score(raw),
                        "raw": raw, "price": gd.item_price(iid), "reason": self.reason(fit_text, rf),
                        "wr": sf["wr"] if sf else None, "stat_text": (sf["text"] if sf else "") + "\n" + parts_txt})
        out = self.smooth(me, out)
        owned = set(me.items)
        for it in out[:k]:
            it["hint"] = self.buy_hint(it["id"], gold, owned)
        boots = self.recommend_boots(me, t, prof, role, cs, gold, legend, phase)
        return ([boots] if boots else []) + out[:k], prof

    def db_factor(self, me, kind, key, cap):
        """自建数据库（你用 Riot 密钥收集的海斗对局）：这个英雄出这件 / 拿这个增幅时的胜率，
        对比这个英雄的平均；有你段位的足够样本就只看你的段位。加分 = clamp(6 × 收缩后的胜率差, ±cap)"""
        db = getattr(self, "riotdb", None)
        if db is None:
            return None
        champ = (self.gd.champ(me.cid) or {}).get("id", me.cid)
        c = db.champ(champ)
        if not c or c["n"] < 100:
            return None
        tier = db.cfg.get("my_tier")
        label = tr("自建库")
        if kind == "items" and tier and c["tiers"].get(tier, [0])[0] >= 100:
            n_all, w_all = c["tiers"][tier]
            row = c["items_t"].get((tier, key))
            label = tr('自建库·{0}').format(tier_name(tier))
        else:
            n_all, w_all = c["n"], c["w"]
            row = c[kind].get(key)
        if not row or row[0] < 20:
            return None
        base = w_all / n_all
        lift = (row[1] / row[0] - base) * row[0] / (row[0] + 200)
        v = max(-cap, min(cap, 6 * lift))
        if abs(v) < 0.015:
            return None
        return (v, tr('{0} {1} 局里出现 {2} 次，胜率 {3:.0f}%（{4:+.0f}%）').format(
            label, n_all, row[0], 100 * row[1] / row[0], 100 * (row[1] / row[0] - base)))

    def habit_summary(self, me):
        hp = self.habit_profile(me)
        if not hp or hp["games"] < 1:
            return ""
        wr = tr('，胜率 {0:.0f}%').format(100 * hp["wins"] / hp["decided"]) if hp["decided"] else ""
        top = sorted(hp["items"].items(), key=lambda x: -x[1][0])[:3]
        items = tr("、").join(self.gd.item_name(i) for i, _ in top)
        return tr('你的{0}：{1} 局{2}').format(self.gd.champ_name(me.cid), hp["games"], wr) + \
            (tr('；常出 {0}').format(items) if items else "")

    def habit_profile(self, me):
        store = getattr(self, "habits_store", None)
        if store is None or not store.enabled:
            return None
        champ = (self.gd.champ(me.cid) or {}).get("id", me.cid)
        return store.profile(champ)

    def habit_item(self, me, iid):
        hp = self.habit_profile(me)
        if not hp or hp["games"] < 2:
            return None
        cnt, wins = hp["items"].get(iid, (0, 0))
        b = habit_bonus(cnt, wins, hp["games"], hp["wins"], hp["decided"], 0.10)
        if b < 0.01:
            return None
        return (b, tr('你常出（{0} 局里出了 {1} 局，赢 {2} 局）').format(hp["games"], cnt, wins))

    def habit_aug(self, me, a):
        hp = self.habit_profile(me)
        if not hp or hp["games"] < 2:
            return None
        cnt, wins = hp["augs"].get(a["name"], (0, 0))
        seen = max(cnt, hp["offered"].get(a["name"], 0))
        if not cnt or seen < 1:
            return None
        # 增幅：用「出现时你选它的比例」当熟悉度
        b = habit_bonus(cnt, wins, max(seen, 2), hp["wins"], hp["decided"], 0.15)
        if b < 0.01:
            return None
        return (b, tr('你常拿（出现 {0} 次选了 {1} 次，赢 {2} 局）').format(seen, cnt, wins))

    def champ_traits(self, cid):
        """阵容用：AP 为主？前排？开团？治疗/保护？"""
        c = self.gd.champ(cid) or {}
        info = c.get("info", {"attack": 5, "magic": 5, "defense": 5})
        tags = set(c.get("tags", []))
        o = CHAMP_OVERRIDE.get(c.get("id", cid), {})
        ap = o.get("AP", 0) > o.get("AD", 0) if o else info.get("magic", 5) > info.get("attack", 5)
        return {"ap": ap, "front": "Tank" in tags or (champ_role(self.gd, cid, "engage") and "Fighter" in tags),
                "engage": champ_role(self.gd, cid, "engage"),
                "sustain": champ_role(self.gd, cid, "enchanter") or champ_role(self.gd, cid, "heal") and "Support" in tags,
                "poke": champ_role(self.gd, cid, "poke")}

    def rank_champions(self, cands, team, mine=None):
        """选英雄阶段：给你现在的英雄和备选席上的英雄打分
           分数 = 100 × (0.55 × 海斗胜率项 + 0.25 × 你的战绩项 + 0.20 × 阵容项)
             海斗胜率项 = clamp(0.5 + 8 × (胜率 − 50%) × n/(n+5000), 0, 1)        （还没下载到 = 0.5）
             你的战绩项 = ½ × √(min(局数, 20)/20) + ½ × clamp(0.5 + 2 × (平滑胜率 − 50%), 0, 1)
             阵容项     = 0.3 + 补上队伍缺的（前排 / 魔法伤害 / 开团 / 治疗保护）每项 +0.25，最高 1"""
        store = getattr(self, "habits_store", None)
        tr_team = [self.champ_traits(c) for c in team]
        need = {"front": not any(x["front"] for x in tr_team),
                "ap": sum(1 for x in tr_team if x["ap"]) <= (0 if len(team) < 3 else 1),
                "engage": not any(x["engage"] for x in tr_team),
                "sustain": not any(x["sustain"] for x in tr_team)}
        label = {"front": tr("前排"), "ap": tr("魔法伤害"), "engage": tr("开团"), "sustain": tr("治疗/保护")}
        out = []
        for cid in cands:
            c = self.gd.champ(cid)
            if not c:
                continue
            cs = self.stats.get(c.get("key"), light=True) if self.stats else None
            reasons = []
            if cs and cs.get("n"):
                W = max(0.0, min(1.0, 0.5 + 8 * (cs["wr"] - 0.5) * cs["n"] / (cs["n"] + 5000)))
                reasons.append(tr('海斗胜率 {0:.1f}%').format(cs["wr"] * 100) +
                               (tr('（{0} 级）').format(cs["tier"]) if cs.get("tier") else ""))
                wr = cs["wr"]
            else:
                W, wr = 0.5, None
            U = 0.5
            if store is not None and store.enabled:
                hp = store.profile(c["id"])
                if hp["games"]:
                    fam = math.sqrt(min(hp["games"], 20) / 20)
                    pw = (hp["wins"] + 1) / (hp["decided"] + 2) if hp["decided"] else 0.5
                    U = 0.5 * fam + 0.5 * max(0.0, min(1.0, 0.5 + 2 * (pw - 0.5)))
                    reasons.append(tr('你 {0} 局 {1} 胜').format(hp["games"], hp["wins"]))
                else:
                    U = 0.25
            t = self.champ_traits(cid)
            fills = [k for k in need if need[k] and t[k]]
            C = min(1.0, 0.3 + 0.25 * len(fills))
            if fills:
                reasons.append(tr('补上队伍缺的{0}').format(tr("、").join(label[k] for k in fills)))
            score = 100 * (0.55 * W + 0.25 * U + 0.20 * C)
            out.append({"id": cid, "name": c["name"], "score": int(round(score)), "raw": score / 100, "wr": wr,
                        "reason": tr("，").join(reasons) or tr("暂无数据"), "mine": cid == mine,
                        "hint": tr("你现在的英雄") if cid == mine else ""})
        out.sort(key=lambda x: -x["raw"])
        return out, [label[k] for k in need if need[k]]

    def shopping_plan(self, me, gold, rec_items, max_targets=2):
        """阵亡时用手上的钱怎么买：按推荐顺序，先凑第一件（钱够就直接合成，不够就买最贵的零件），
        有剩再往下一件。回传 {"buy": [(编号, 价钱)], "left": 剩下的钱, "targets": [名称], "done": [合成完成的名称]}"""
        gd = self.gd
        owned = Counter(me.items)

        def base(i):
            g = gd.items.get(i, {}).get("gold", {})
            return g.get("base", g.get("total", 0))

        def comps(i):
            return [int(c) for c in gd.items.get(i, {}).get("from", []) if str(c).isdigit()]

        def cost(i, own):
            """合成 i 还要花多少（会用掉 own 里已有的零件）"""
            if own[i] > 0:
                own[i] -= 1
                return 0
            return base(i) + sum(cost(c, own) for c in comps(i))

        def buy(i, budget, own):
            trial = Counter(own)
            need = cost(i, trial)
            if need <= budget:
                own.clear()
                own.update(trial)
                own[i] += 1
                return [(i, need)], need
            bought, spent = [], 0
            for c in sorted(comps(i), key=lambda c: -gd.item_price(c)):
                if own[c] > 0:
                    own[c] -= 1                       # 已有的零件留着（合成时要用）
                    continue
                b, sp = buy(c, budget - spent, own)
                bought += b
                spent += sp
            return bought, spent

        plan, left, targets, done = [], int(gold), [], []
        for it in rec_items:
            if len(targets) >= max_targets or left < 300:
                break
            iid = it.get("id")
            if not iid or iid in me.items:
                continue
            own = Counter(owned)
            bought, spent = buy(iid, left, own)
            if not bought:
                continue
            targets.append(gd.item_name(iid))
            if any(b == iid for b, _ in bought):
                done.append(gd.item_name(iid))
            plan += bought
            left -= spent
            owned = own
        return {"buy": plan, "left": left, "targets": targets, "done": done}

    @staticmethod
    def item_score(raw):
        """装备分数 = 100 × raw / 0.85（raw 是 0~1 的加权和；0.85 以上即满分，让好装备落在 70~90）"""
        return max(1, min(99, int(round(100 * raw / 0.85))))

    @staticmethod
    def item_formula(fit, sf, factors, wts):
        """装备推荐公式（详见 README「推荐公式」）：
            raw = wF·F + wP·P + wW·W + wS·S + N
            F 契合度 = 装备属性与你的出装方向的余弦相似度（< 0.35 的不推荐）
            P 热门度 = √(min(pop, 40%) / 40%)，pop = 这一件时的购买占比 / 整局购买率×½ / 路线里下一件是它的比例 取最高
            W 胜率   = clamp(0.5 + 6·lift, 0, 1)，lift = 收缩后的胜率差（见 item_stat_factor）
            S 本局针对 = min(1, Σ正面因素 / 0.4) × 契合闸门 × 热门闸门
            N 扣分   = Σ负面因素（暴击已满、重伤重复、对面重伤多时的吸血…）；pop < 0.5% 再 −0.10
          没有网上数据时 P=0.4、W=0.5（中性），热门闸门=0.6。"""
        wF, wP, wW, wS = wts
        pos = sum(v for v, _ in factors if v > 0)
        neg = sum(v for v, _ in factors if v < 0)
        gate_fit = min(1.0, max(0.0, (fit - 0.3) / 0.4))       # 不合定位的装备，针对加分打折
        if sf is not None:
            pop = sf["pop"]
            P = math.sqrt(min(pop, 0.4) / 0.4)
            W = max(0.0, min(1.0, 0.5 + 6 * sf["lift"]))
            gate_pop = min(1.0, 0.3 + pop / 0.03)             # 这个英雄几乎没人出的装备，针对加分打折
            if pop < 0.005:
                neg -= 0.10
        else:              # 网上数据还没载入 / 连不上：热门度、胜率取中性值，针对加分打六折
            P, W = 0.4, 0.5
            gate_pop = 0.6
        S = min(1.0, pos / 0.4) * gate_fit * gate_pop
        raw = wF * fit + wP * P + wW * W + wS * S + neg
        txt = "F{0:.2f}×{1:.2f} + P{2:.2f}×{3:.2f} + W{4:.2f}×{5:.2f} + S{6:.2f}×{7:.2f} {8:+.2f} = {9:.2f}".format(
            fit, wF, P, wP, W, wW, S, wS, neg, raw)
        return raw, txt

    def smooth(self, me, out):
        """让推荐平滑：分数随时间渐变（不因一次阵亡/买装就大跳），
        排第一的装备只有在别的明显更好、或你已经买了它时才会换掉。"""
        if getattr(self, "_ema_cid", None) != me.cid:      # 换英雄（新的一局）就重来
            self._ema_cid, self._ema, self._top = me.cid, {}, None
        for it in out:
            prev = self._ema.get(it["id"])
            if prev is not None:
                it["raw"] = 0.55 * it["raw"] + 0.45 * prev
            self._ema[it["id"]] = it["raw"]
            it["score"] = self.item_score(it["raw"])
        out.sort(key=lambda x: -x["raw"])
        if out and self._top is not None and out[0]["id"] != self._top:
            keep = next((i for i, x in enumerate(out) if x["id"] == self._top), None)
            if keep is not None and out[keep]["raw"] >= out[0]["raw"] - 0.03:
                out.insert(0, out.pop(keep))
        if out:
            self._top = out[0]["id"]
        return out

    def recommend_boots(self, me, t, prof, role, cs, gold, legend, phase):
        """还没有二级鞋时，单独推荐一双：网上这个英雄的鞋子胜率 + 本局对面阵容"""
        gd = self.gd
        if any(gd.is_boots(i) and gd.item_price(i) >= 900 for i in me.items):
            return None
        allowed = self.stats.item_allow if self.stats else None
        best = None
        for iid in gd.candidate_items(ITEM_MAP["aram"], allowed):
            if not gd.is_boots(iid) or gd.item_price(iid) < 900:
                continue
            vec, special = gd.item_vec(iid)
            nv = norm({d: v for d, v in vec.items() if d in BUILD_DIMS and d != "MS"})
            fit = max(0.5, cosine(prof, nv)) if nv else 0.5      # 鞋子人人要买，契合度给个底
            ehp = self.ehp_factor(iid, me, t, prof, role)
            factors = self.counter_factors(vec, special, t, prof, ehp_done=ehp is not None, phase=1.0)
            if ehp and ehp[0] > 0.03:
                factors.append(ehp)
            sf = None
            if cs:          # 鞋子：和所有鞋子的平均比；热门度＝整局购买率（一局只买一双）
                boots_rows = {i: r for i, r in cs["items"].items() if gd.is_boots(i) and gd.item_price(i) >= 900}
                r = boots_rows.get(iid)
                base = self._wmean(boots_rows)
                if r and base:
                    sf = {"lift": self._shrink(r["wr"] - base, r["n"], 20000), "raw": r["wr"] - base,
                          "wr": r["wr"], "pop": r["pick"],
                          "text": tr('网上胜率 {0:.1f}%（比平均{1:+.1f}%）').format(r["wr"] * 100, (r["wr"] - base) * 100) +
                          (tr('，{0:.0f}% 的人买').format(r["pick"] * 100) if r["pick"] >= 0.1 else "")}
                else:
                    sf = {"lift": 0.0, "raw": 0.0, "wr": None, "pop": 0.0, "text": ""}
            raw, parts_txt = self.item_formula(fit, sf, factors, ITEM_WEIGHTS[0][0])
            if best is None or raw > best[0]:
                rf = [f for f in factors if f[0] > 0 or f[0] <= -0.05] + \
                    ([(0.1, sf["text"])] if sf and sf["text"] else [])
                best = (raw, iid, rf, sf, parts_txt)
        if not best:
            return None
        raw, iid, rf, sf, parts_txt = best
        dims = self.top_dims(prof, norm({d: v for d, v in gd.item_vec(iid)[0].items() if d != "MS"}))
        return {"name": "👟 " + gd.item_name(iid), "id": iid, "score": self.item_score(raw), "raw": raw,
                "stat_text": (sf["text"] if sf else "") + "\n" + parts_txt,
                "price": gd.item_price(iid), "boots": True, "wr": sf["wr"] if sf else None,
                "reason": self.reason(tr('契合你的{0}路线').format('/'.join(dims)) if dims else "", rf),
                "hint": self.buy_hint(iid, gold, set(me.items))}

    # ---------- augments ----------
    def score_aug(self, a, prof, t, my_augs, me, cs=None, stage=1):
        tags = a["tags"]
        bv = norm({d: v for d, v in tags.items() if d in BUILD_DIMS})
        if bv:
            fit = cosine(prof, bv)
            dims = self.top_dims(prof, bv)
            fit_text = tr('强化你的{0}').format('/'.join(dims)) if dims else tr("与你的定位关系不大")
        elif tags:
            fit, fit_text = 0.35, tr("功能型增幅，不挑出装")
        elif a.get("desc"):
            fit, fit_text = 0.33, tr("通用型增幅，效果不挑英雄")
        else:
            fit, fit_text = 0.3, tr("描述未收录，按中性估算")
        special = {d for d in tags if d in ("ANTIHEAL", "TENACITY", "SURVIVE", "MAXHP_DMG", "TRUE", "ANTICRIT")}
        factors = self.counter_factors(dict(tags), special, t, prof, kind="aug")
        for m in my_augs:
            if m["name"] != a["name"] and bv and cosine(norm(m["tags"]), bv) > 0.55:
                factors.append((0.08, tr('和已选「{0}」同一套路可叠加').format(m['name'])))
                break
        owned = self.items_profile(me.items)
        if owned and bv and cosine(owned, bv) > 0.6:
            factors.append((0.06, tr("和你现有装备属性吻合")))
        champ = (self.gd.champ(me.cid) or {}).get("id", me.cid)
        combo = getattr(self.gd, "am_combos", {}).get((str(champ).lower(), a["name"]))
        combo_f = (0.15, tr("arammayhem.com 标注为这个英雄的强力组合")) if combo == "good" else \
            (-0.2, tr("arammayhem.com 标注为这个英雄的陷阱组合")) if combo == "bad" else None
        gate = 0.6 if not bv else min(1.0, max(0.2, (fit - 0.2) / 0.4))
        situ = sum(v * (gate if v > 0 else 1) for v, _ in factors)
        sf = self.aug_stat_factor(a, cs, stage, [m["id"] for m in my_augs if m.get("id")])
        # 国服整体选取率（arammayhem.com）：大家常拿的增幅小幅加分，冷门的小幅扣分；
        # 编辑整理的「这个英雄 + 这个增幅」强力 / 陷阱组合不受契合度打折（是针对这个英雄的）
        am_pick = a.get("am_pick")
        pop = 0.12 * (math.sqrt(min(am_pick, 0.6) / 0.6) - 0.4) if am_pick is not None else 0.0
        if combo_f:
            situ += combo_f[0]
            factors.insert(0, combo_f)
        dbf = self.db_factor(me, "augs", a.get("id"), 0.12) if a.get("id") else None
        if dbf:                          # 自建数据库：±最多 0.12
            situ += dbf[0]
            factors.insert(0, dbf)
        hab = self.habit_aug(me, a)
        if hab:                          # 你的习惯：+最多 0.15
            situ += hab[0]
            factors.insert(0, hab)
        if sf:
            # 有这个英雄的实战胜率：以胜率为主，本局分析做修正（通用型增幅不会因为「不挑英雄」吃亏）
            raw = 0.2 + 0.35 * fit + situ + 0.03 * a.get("rarity", 0) + min(0.55, sf[0] * 1.3) + pop
        else:
            raw = 0.12 + 0.55 * fit + situ + 0.05 * a.get("rarity", 0) + 1.5 * pop
        rf = factors + ([(sf[0], sf[1])] if sf and abs(sf[0]) >= 0.08 else [])
        if am_pick is not None and (am_pick >= 0.3 or am_pick < 0.03):
            rf.append((0.05 if am_pick >= 0.3 else -0.05, tr('国服选取率 {0:.0f}%').format(am_pick * 100)))
        return {"name": a["name"], "score": self.to_score(raw), "raw": raw,
                "rarity": a.get("rarity", 0), "reason": self.reason(fit_text, rf),
                "known": bool(a.get("desc")), "wr": sf[2] if sf else None, "stat_text": sf[1] if sf else ""}

    def recommend_augs(self, me, my_augs, t, candidates, k=5, cs=None):
        prof = self.my_profile(me, my_augs)
        stage = max(1, min(4, len(my_augs) + 1))
        if candidates:
            res = [self.score_aug(a, prof, t, my_augs, me, cs, stage) for a in candidates]
            res.sort(key=lambda x: -x["raw"])
            return res
        mine = {a["name"] for a in my_augs}
        res = [self.score_aug(a, prof, t, my_augs, me, cs, stage) for a in self.aug_index.values()
               if a["name"] not in mine and a.get("desc")]
        res.sort(key=lambda x: -x["raw"])
        return res[:k]

    # ---------- 战术 ----------
    def tactics(self, me, allies, enemies, t, prof, my_augs):
        """回传 [(优先度, 文字, 是否紧急)]"""
        gd = self.gd
        tips = []
        role = self.role_of(me, prof)
        cn = gd.champ_name
        alive_e = [e for e in enemies if not e.is_dead]
        dead_e = [e for e in enemies if e.is_dead]
        dead_a = [p for p in allies + [me] if p.is_dead]
        # 1) 人数差（最即时）
        if not me.is_dead and dead_e and len(dead_e) - len(dead_a) >= 2:
            back = min(e.respawn for e in dead_e)
            tips.append((100, tr('敌方 {0} 人阵亡（{1:.0f} 秒后有人复活）→ 立刻推塔、打团').format(len(dead_e), back), True))
        elif not me.is_dead and t.get("carry") is not None and t["carry"].is_dead and t["carry"].respawn > 8:
            tips.append((92, tr('敌方核心{0}阵亡 {1:.0f} 秒 → 趁现在开团').format(t['carry_name'], t['carry'].respawn), True))
        if len(dead_a) - len(dead_e) >= 2:
            tips.append((98, tr('我方少 {0} 人 → 退塔下守，等队友复活别接团').format(len(dead_a) - len(dead_e)), True))
        s = me.stats or {}
        if not me.is_dead and s.get("maxHealth") and s.get("currentHealth", 1e9) / s["maxHealth"] < 0.3:
            tips.append((90, tr("血量低于 30% → 先吃血包或退后，别硬接团"), True))
        # 2) 整体实力
        diff = t["power_diff"]
        if diff > 2500:
            tips.append((62, tr('我方装备/人头领先约 {0:.1f}k → 主动找团、压塔，别给对面拖时间').format(diff / 1000), False))
        elif diff < -2500:
            tips.append((62, tr('我方落后约 {0:.1f}k → 避战清兵，等对面失误或技能交完再反打').format(-diff / 1000), False))
        # 3) 集火目标：最肥且最脆的敌人
        target = None
        if alive_e:
            def fscore(e):
                tags = (gd.champ(e.cid) or {}).get("tags", [])
                squishy = 1.4 if tags[:1] in (["Marksman"], ["Mage"], ["Assassin"]) else \
                    0.6 if "Tank" in tags else 1.0
                # 海斗平衡：承受伤害高的更好杀，造成伤害高的更该先杀
                return self.power(e) * squishy * (1 + self.bal(e.cid, "damageTaken")) * \
                    (1 + self.bal(e.cid, "damageDealt"))
            target = max(alive_e, key=fscore)
            val = sum(gd.item_price(i) for i in target.items)
            tips.append((70, tr('集火 {0}').format(cn(target.cid)) + (tr('（{0}/{1}，装备 {2:.1f}k）').format(target.kills, target.deaths, val / 1000)
                                                        if val >= 1000 else tr("（最脆的输出位）")), False))
        tname = cn(target.cid) if target else tr("敌方后排")
        self._focus = cn(target.cid) if target else ""
        protect = [cn(p.cid) for p in allies if self.role_of(p) in ("adc", "mage")]
        front = t["ally_tanks"] or [cn(p.cid) for p in allies if self.role_of(p) in ("tank", "fighter")]
        # 4) 你的打法
        burst = [b for b in t["burst"]]
        role_tip = {
            "tank": tr('你是前排：先手开 {0}，吃掉技能给后排输出').format(tname),
            "fighter": tr('你是战士：从侧面进场找 {0}，别当第一个吃技能的').format(tname),
            "adc": tr('你是主C：站在{0}身后，打最近的安全目标').format(front[0] if front else tr('队友'))
                   + (tr('；小心 {0} 切入，保留位移/保命').format(tr('、').join(burst[:2])) if burst else ""),
            "mage": tr('你是法师：保持距离消耗，技能留给 {0}').format(tname),
            "assassin": tr('你是刺客：等对面交出控制再切 {0}，一套秒掉就走').format(tname),
            "support": tr('你是辅助：保护{0}，护盾/补血优先给他').format(protect[0] if protect else tr('主C')),
        }[role]
        tips.append((75, role_tip, False))
        # 5) 阵容对位
        if len(t["ally_poke"]) >= 2 and len(t["enemy_engage"]) >= 2:
            tips.append((58, tr('我方消耗型、敌方开团强（{0}）→ 拉开距离先磨血，别挤一起').format(tr('、').join(t['enemy_engage'][:2])), False))
        elif len(t["enemy_poke"]) >= 2 and len(t["ally_engage"]) >= 1:
            tips.append((58, tr('敌方消耗型（{0}）→ 别在外面被磨，找 {1} 直接开').format(tr('、').join(t['enemy_poke'][:2]), t['ally_engage'][0]), False))
        elif len(t["ally_engage"]) >= 2 and len(t["enemy_engage"]) <= 1:
            tips.append((50, tr('我方开团能力强（{0}）→ 跟着先手一起进').format(tr('、').join(t['ally_engage'][:2])), False))
        if t["heal"] >= 2 and not t["team_antiheal"]:
            tips.append((57, tr("敌方回复强、我方没重伤 → 打爆发，别打持久战"), False))
        if len(t["cc"]) >= 3:
            tips.append((52, tr('敌方控制多（{0}）→ 分散站位，别被一次控多人').format(tr('、').join(t['cc'][:3])), False))
        if len(t["tanks"]) >= 2 and role in ("adc", "mage", "assassin"):
            tips.append((48, tr('敌方前排厚（{0}）→ 打得到后排才进，打不到就先打前排').format(tr('、').join(t['tanks'][:2])), False))
        # 6) 增幅带来的打法
        tags = Counter()
        for a in my_augs:
            tags.update(a["tags"])
        if tags.get("SURVIVE"):
            tips.append((46, tr("你有保命类增幅 → 可以更积极进场"), False))
        if tags.get("ULT"):
            tips.append((45, tr("增幅强化大绝 → 以大绝为开团信号，大绝好了再打"), False))
        if tags.get("MS"):
            tips.append((40, tr("有跑速增幅 → 多绕侧翼找角度"), False))
        etags = Counter()
        for a in t.get("enemy_augs", []):
            etags.update(a["tags"])
        if etags.get("SURVIVE"):
            tips.append((44, tr("敌方有保命增幅 → 击杀要留一段伤害补刀"), False))
        tips.sort(key=lambda x: -x[0])
        return tips[:4]

    # ---------- 敌方增幅预警 ----------
    EAUG_W = {"SURVIVE": 2.0, "SUSTAIN": 1.5, "HEALSHIELD": 1.5, "TRUE": 1.5, "MAXHP_DMG": 1.5, "ULT": 1.0,
              "TENACITY": 1.0, "ARMOR": 1.0, "MR": 1.0, "HP": 0.8, "CRIT": 0.8, "AS": 0.8, "ONHIT": 0.8,
              "AD": 0.6, "AP": 0.6, "LETHAL": 0.8, "MPEN": 0.8, "MS": 0.5, "HASTE": 0.5}

    def enemy_aug_alerts(self, me, enemies, manual_enemy):
        """敌方每个增幅：危险度 + 一句怎么应对。回传按危险度排序的 [{"who","aug","fix","danger","key"}]"""
        ad_me = self.dmg_split(me) > 0.5
        has_ah = any("ANTIHEAL" in self.gd.item_vec(i)[1] for i in me.items)
        fixes = {
            "SUSTAIN": tr("已有重伤") if has_ah else tr("出重伤"),
            "HEALSHIELD": tr("已有重伤") if has_ah else tr("出重伤"),
            "SURVIVE": tr("留伤害补刀"), "TRUE": tr("双抗没用，堆血"), "MAXHP_DMG": tr("别堆血，出双抗"),
            "ULT": tr("躲他大招"), "TENACITY": tr("控制会变短"),
            "ARMOR": tr("出破甲") if ad_me else tr("打别人"), "HP": tr("出百分比伤害"),
            "MR": tr("出法穿") if not ad_me else tr("打别人"),
            "CRIT": tr("出护甲"), "AS": tr("出护甲"), "ONHIT": tr("出护甲"), "AD": tr("出护甲"),
            "LETHAL": tr("出护甲"), "AP": tr("出魔抗"), "MPEN": tr("出魔抗"),
            "MS": tr("留控制给他"), "HASTE": tr("别站一起"),
        }
        pairs = [(p, n) for p in enemies for n in p.augments] + [(None, n) for n in manual_enemy]
        out, seen = [], set()
        for p, n in pairs:
            a = self.find_aug(n)
            if not a or (p and p.cid, a["name"]) in seen:
                continue
            seen.add((p and p.cid, a["name"]))
            tags = a.get("tags", {})
            ranked = sorted((k for k in tags if k in self.EAUG_W), key=lambda k: -self.EAUG_W[k] * tags[k])
            danger = 0.7 * a.get("rarity", 0) + sum(self.EAUG_W.get(k, 0) * min(2, v) for k, v in tags.items())
            out.append({"who": self.gd.champ_name(p.cid) if p else tr("敌方"), "aug": a["name"],
                        "fix": fixes[ranked[0]] if ranked else "", "danger": danger,
                        "key": (p.cid if p else "", a["name"])})
        out.sort(key=lambda x: -x["danger"])
        return out

    # ---------- 战况条：连招 / 战局 / 威胁 / 玩法，每行几个字 ----------
    def brief(self, me, allies, enemies, t, prof, guide, ealerts=()):
        """回传 [(标签, 文字, 是否紧急)]"""
        cn = self.gd.champ_name
        out = []
        if guide.get("combo_keys"):
            out.append((tr("连招"), guide["combo_keys"], False))
        dead_e = sum(1 for e in enemies if e.is_dead)
        dead_a = sum(1 for p in allies + [me] if p.is_dead)
        s = me.stats or {}
        if not me.is_dead and dead_e - dead_a >= 2:
            state, hot = tr("敌少{0}人 → 推").format(dead_e - dead_a), True
        elif dead_a - dead_e >= 2:
            state, hot = tr("我少{0}人 → 退守").format(dead_a - dead_e), True
        elif not me.is_dead and s.get("maxHealth") and s.get("currentHealth", 1e9) / s["maxHealth"] < 0.3:
            state, hot = tr("残血 → 后撤"), True
        elif not me.is_dead and t.get("carry") is not None and t["carry"].is_dead and t["carry"].respawn > 8:
            state, hot = tr("{0}阵亡 → 开团").format(t["carry_name"]), True
        else:
            d = t["power_diff"]
            lead = tr("领先{0:.1f}k").format(d / 1000) if d > 500 else tr("落后{0:.1f}k").format(-d / 1000) \
                if d < -500 else tr("均势")
            state, hot = lead + " · " + "{0}:{1}".format(t["kills_ally"], t["kills_enemy"]), False
        out.append((tr("战局"), state, hot))
        if enemies:
            def pw(e):
                return self.power(e) * (1 + self.bal(e.cid, "damageDealt")) * \
                    (0.6 if "Tank" in (self.gd.champ(e.cid) or {}).get("tags", []) else 1.0)
            tags = [(t["burst"], tr("爆发")), (t["enemy_engage"], tr("开团")), (t["cc"], tr("控制")),
                    (t["healers"], tr("回复")), (t["enemy_poke"], tr("消耗"))]
            role = {"tank": tr("坦"), "fighter": tr("战士"), "adc": tr("输出"), "mage": tr("输出"),
                    "assassin": tr("刺客"), "support": tr("辅助")}
            parts = []
            for e in sorted(enemies, key=lambda e: (not e.is_dead, pw(e)), reverse=True)[:2]:   # 活着的优先
                nm = cn(e.cid)
                tag = next((lb for names, lb in tags if nm in names), role[self.role_of(e)])
                parts.append(nm + " " + tag + (tr("(亡)") if e.is_dead else ""))
            out.append((tr("威胁"), " · ".join(parts), False))
        style = {"tank": tr("先手开团"), "fighter": tr("侧翼进场"), "adc": tr("躲前排后输出"),
                 "mage": tr("远距消耗"), "assassin": tr("等控制交完再切"), "support": tr("保护主C")}[self.role_of(me, prof)]
        focus = getattr(self, "_focus", "")
        out.append((tr("玩法"), style + (" · " + tr("打{0}").format(focus) if focus else ""), False))
        if ealerts:
            now = time.time()
            first = self.__dict__.setdefault("_eaug_seen", {})
            for x in ealerts:
                first.setdefault(x["key"], now)
            # 刚出现的（30 秒内）排最前、标橙色
            fresh = [x for x in ealerts if now - first[x["key"]] < 30]
            top = (fresh or ealerts)[0]
            txt = tr("{0}「{1}」").format(top["who"], top["aug"]) + (" → " + top["fix"] if top["fix"] else "")
            if len(ealerts) > 1:
                txt += " +{0}".format(len(ealerts) - 1)
            out.append((tr("敌增幅"), txt, bool(fresh)))
        return out

    # ---------- 英雄玩法 / 连招 ----------
    MOBILITY = r"冲刺|突进|跳跃|跃向|跃起|跃至|闪烁|传送|位移|冲向|冲锋|飞向|瞬移|翻滚|(?i:dash|leap|lunge|blink|teleport|jump|charges?\b)"
    CONTROL = r"晕眩|眩晕|击飞|禁锢|定身|嘲讽|魅惑|恐惧|沉默|压制|击退|缠绕|睡眠|拉向|拉回|束缚|冰冻|(?i:stun|knock|root|taunt|charm|fear|silence|suppress|snare|sleep|pull|airborne)"

    def combo_text(self, combo, kit):
        """「E>Q>R」→「E 名称 → Q 名称 → R 名称」"""
        special = {"A": tr("普攻"), "闪": tr("闪现"), "草": tr("草丛")}
        out = []
        for tok in combo.split(">"):
            tok = tok.strip()
            key = tok[:1]
            if kit and key in "QWER" and key in kit and (len(tok) == 1 or tok[1:] in ("2", "黄", "红", "Q")):
                extra = {"2": tr("二段"), "黄": tr("黄牌"), "红": tr("红牌")}.get(tok[1:], tok[1:])
                out.append(tr("{0}「{1}」{2}").format(key, kit[key]["name"], extra).strip())
            else:
                out.append(special.get(tok, tok))
        return " → ".join(out)

    def auto_combo(self, kit, role):
        """没收录的英雄：按技能描述推导「位移接近 → 控制 → 伤害 → 大招」"""
        mob, cc, dmg = [], [], []
        for k in "QWE":
            d = kit[k]["desc"]
            if re.search(self.MOBILITY, d):
                mob.append(k)
            elif re.search(self.CONTROL, d):
                cc.append(k)
            else:
                dmg.append(k)
        rd = kit["R"]["desc"]
        r_buff = bool(re.search(r"升级.{0,6}技能|强化.{0,6}技能|进入.{0,8}状态|变身|形态|(?i:transform|empower|enhanced|form)", rd))
        r_first = bool(re.search(self.MOBILITY, rd) and re.search(self.CONTROL, rd)) or r_buff
        seq = (["R"] if r_first else []) + mob + cc + dmg + ([] if r_first else ["R"])
        parts = []
        if mob:
            parts.append(tr('{0}接近').format(tr('、').join(kit[k]['name'] for k in mob)))
        if cc:
            parts.append(tr('{0}控制').format(tr('、').join(kit[k]['name'] for k in cc)))
        if r_buff:
            parts.insert(0, tr("先开大招强化技能"))
            parts.append(tr("再打出伤害"))
        else:
            parts.append(tr("再打出伤害") + (tr("，大招开团") if r_first else tr("，大招收尾")))
        return [(">".join(seq), tr("按技能描述推导：") + tr("，").join(parts))]

    def champ_guide(self, me, cs, prof):
        kit = self.gd.champ_kit(me.cid)
        g = {"combos": [], "style": "", "skills": "", "spells": "", "auto": False,
             "habit": getattr(self, "_habit_line", "")}
        if me.cid in COMBOS:
            combos, g["style"] = COMBOS[me.cid]
            en = COMBOS_EN.get(me.cid) if LANG == "en" else None
            if en:   # 英文：连招说明和玩法用翻译好的版本
                notes, g["style"] = en.get("notes", []), en.get("style", g["style"])
                combos = [(c, notes[i] if i < len(notes) else n) for i, (c, n) in enumerate(combos)]
        elif kit:
            combos, g["auto"] = self.auto_combo(kit, self.role_of(me, prof)), True
            g["style"] = tr("新英雄，连招按技能描述推导，仅供参考")
        else:
            combos = []
        g["combos"] = [(self.combo_text(c, kit), note) for c, note in combos[:2]]
        if combos:
            short = {"A": tr("平A"), "闪": tr("闪"), "草": tr("草")}
            g["combo_keys"] = "→".join(short.get(x.strip(), x.strip()) for x in combos[0][0].split(">"))
        if self.stats and self.stats.balance:
            b = self.stats.balance.get(me.cid.lower()) or {}
            label = {"damageDealt": tr("造成伤害"), "damageTaken": tr("承受伤害"), "abilityHaste": tr("技能急速"),
                     "healing": tr("治疗"), "shielding": tr("护盾"), "tenacity": tr("韧性"), "energyRegen": tr("能量回复"),
                     "attackSpeed": tr("攻速")}
            parts = []
            for k, v in b.get("mods", {}).items():
                if not v:
                    continue
                num = f"{v * 100:+.0f}%" if abs(v) < 5 else f"{v:+.0f}"
                parts.append(f"{label.get(k, k)} {num}")
            for key, ability, lines in b.get("changes", [])[:2]:
                if lines:
                    parts.append(tr('{0}「{1}」{2}').format(key, ability, lines[0]))
            g["balance"] = tr("海斗平衡：") + (tr("，").join(parts) if parts else tr("无调整"))
        if cs and cs.get("skills"):
            order, wr, pick, n = max(cs["skills"], key=lambda x: x[2])     # 最多人用的
            ks = order.split(">")
            names = (lambda k: tr('{0}「{1}」').format(k, kit[k]['name']) if kit and k in kit else k)
            g["skills"] = tr('加点：主{0} 副{1}（{2}，{3:.0f}% 的人，胜率 {4:.1f}%）').format(names(ks[0]), names(ks[1]) if len(ks) > 1 else '', order, pick * 100, wr * 100)
            best = max((x for x in cs["skills"] if x[3] >= 20000), key=lambda x: x[1], default=None)
            if best and best[0] != order and best[1] - wr >= 0.01:
                g["skills"] += tr('；胜率最高 {0}（{1:.1f}%）').format(best[0], best[1] * 100)
        if cs and cs.get("summoners") and self.stats:
            sn = self.stats.spell_names or {}
            name = (lambda ids: tr("＋").join(sn.get(i, str(i)) for i in ids))
            pop = max(cs["summoners"], key=lambda x: x[2])
            g["spells"] = tr('召唤师：{0}（{1:.0f}% 的人，胜率 {2:.1f}%）').format(name(pop[0]), pop[2] * 100, pop[1] * 100)
            best = max((x for x in cs["summoners"] if x[3] >= 20000), key=lambda x: x[1], default=None)
            if best and best[0] != pop[0] and best[1] - pop[1] >= 0.01:
                g["spells"] += tr('；胜率最高 {0}（{1:.1f}%）').format(name(best[0]), best[1] * 100)
        return g

    # ---------- full ----------
    def analyze(self, state, manual):
        mode, raw_map, me, allies, enemies, gold = state
        kind = mode_kind(mode, raw_map)
        if kind != "aram":   # 本工具只为海克斯大乱斗服务：其他模式不给任何推荐
            return {"items": [], "augs": [], "tips": [(100, tr('当前模式（{0}）不是海克斯大乱斗，暂停推荐').format(mode), True)],
                    "cand_mode": False, "auto_cand": False, "stats_label": "", "my_augs": [], "guide": {},
                    "game_time": me.game_time, "summary": tr('{0}｜非海斗模式').format(self.gd.champ_name(me.cid)),
                    "gold": gold, "mode": mode}
        map_id = ITEM_MAP["aram"]
        self.set_mode("aram")
        names = []
        for n in me.augments + manual.get("mine", []) + manual.get("picked", []):
            if n and n not in names:
                names.append(n)
        my_augs, seen_names = [], set()
        for n in names:
            a = self.find_aug(n)
            if a and a["name"] not in seen_names:   # 别名（旧译名）也只算一次
                seen_names.add(a["name"])
                my_augs.append(a)
        my_augs = [a for a in my_augs if a]
        ally_augs = [self.find_aug(n) for n in manual.get("ally", [])] + \
                    [self.find_aug(n) for p in allies for n in p.augments]
        enemy_augs = [self.find_aug(n) for n in manual.get("enemy", [])] + \
                     [self.find_aug(n) for p in enemies for n in p.augments]
        ally_augs = [a for a in ally_augs if a]
        enemy_augs = [a for a in enemy_augs if a]
        cands = [self.find_aug(n) for n in manual.get("cand", [])]
        cands = [a for a in cands if a]
        auto = False
        if not cands and manual.get("auto"):
            cands = [self.resolve_seen(*s.split("|", 1)) for s in manual["auto"]]
            auto = True
        t = self.team_threat(enemies, enemy_augs, allies, ally_augs, me)
        cs = self.champ_stats(me.cid)          # 胜率全部来自海斗对局统计
        self._habit_line = self.habit_summary(me)
        items, prof = self.recommend_items(me, allies, enemies, my_augs, t, map_id, gold, cs=cs)
        augs = self.recommend_augs(me, my_augs, t, cands, cs=cs)
        tips = self.tactics(me, allies, enemies, t, prof, my_augs)
        if cs and cs.get("core"):
            legend = sum(1 for i in me.items if self.gd.is_completed(i) and not self.gd.is_boots(i))
            if legend <= 2:
                core = cs["core"][0]
                names = " → ".join(self.gd.item_name(i) for i in core["items"])
                tips.append((66, tr('网上主流核心：{0}（胜率 {1:.1f}%）').format(names, core['wr'] * 100), False))
                tips.sort(key=lambda x: -x[0])
                tips = tips[:4]
        diff = t["power_diff"]
        lead = tr('领先 {0:.1f}k').format(diff / 1000) if diff > 500 else tr('落后 {0:.1f}k').format(-diff / 1000) if diff < -500 else tr("均势")
        summary = (tr('{0}｜{1}｜人头 {2}:{3}｜敌方物理 {4}%').format(self.gd.champ_name(me.cid), lead, t['kills_ally'], t['kills_enemy'], round(t['ad_share'] * 100)) + (tr('｜威胁 {0}').format(t['carry_name']) if t['carry_name'] else "") +
                   (tr('｜网上 {0} 级 胜率 {1:.1f}%').format(cs['tier'], cs['wr'] * 100) if cs else
                    (tr("｜网上胜率载入中…") if self.stats and not self.stats.error else "")))
        shop = None
        if me.is_dead and gold >= 300:              # 阵亡＝可以买东西：复活前该买什么
            shop = self.shopping_plan(me, gold, items)
            shop["respawn"] = me.respawn
            shop["names"] = [self.gd.item_name(i) for i, _ in shop["buy"]]
        guide = self.champ_guide(me, cs, prof)
        ealerts = self.enemy_aug_alerts(me, enemies, manual.get("enemy", []))
        return {"items": items, "augs": augs, "tips": tips, "cand_mode": bool(cands), "auto_cand": auto, "shop": shop,
                "brief": self.brief(me, allies, enemies, t, prof, guide, ealerts), "enemy_augs": ealerts,
                "eaug_visible": any(p.augments for p in allies + enemies),
                "stats_label": self.stats.label() if (self.stats and cs) else "",
                "my_augs": [a["name"] for a in my_augs],
                "guide": guide, "game_time": me.game_time,
                "summary": summary, "gold": gold, "mode": mode}


