# 后台轮询
# --------------------------------------------------------------------------------------
class Engine:
    def __init__(self, gd, source, interval=1.5, stats=None):
        self.gd, self.source, self.interval = gd, source, interval
        self.advisor = Advisor(gd, stats)
        self.stats_dirty = False
        if stats is not None:
            def ready():
                with self.lock:
                    self.stats_dirty = True
                self.wake.set()
            stats.on_ready = ready
        self.manual = {"mine": [], "cand": [], "ally": [], "enemy": [], "auto": [], "picked": []}
        self.overlay_rect = None
        self.wake = threading.Event()
        self.connected = False
        self.lock = threading.Lock()
        self.q = queue.Queue()
        self.last_sig = None
        self.last_state = None
        self.manual_dirty = False
        self.history = []
        self.pending_data = None       # (gd, stats, 说明)：新版本数据，等不在对局中时换上
        self.updater = None
        self.scanning = False          # 正在识别三选一（界面这时刷新得快一点）
        self.habits = HabitStore()
        self.advisor.habits_store = self.habits
        self.riotdb = RiotCollector(gd)
        self.advisor.riotdb = self.riotdb

        def db_new():
            self.riotdb.aggregate()
            self.last_sig = None
            self.wake.set()
        self.riotdb.on_new = db_new
        self.cur_game = None           # 这局的记录：英雄、装备、增幅、出现过的增幅
        self._ended = False            # 已读到 GameEnd（结算画面还连着时不要再记一次）
        self.fails = 0                 # 连续读取失败次数（游戏卡一下不算断线）
        self._raw, self._raw_t = None, 0.0

    def apply_pending(self):
        gd, stats, msg = self.pending_data
        self.pending_data = None
        old_ds = self.advisor.stats.dataset if self.advisor.stats else "all"
        if stats is not None:
            stats.dataset = old_ds
            stats.on_ready = self.advisor.stats.on_ready if self.advisor.stats else None
        # 原地换掉（屏幕识别等地方持有同一个 advisor）
        fresh = Advisor(gd, stats)
        fresh.habits_store = self.habits
        fresh.riotdb = self.riotdb
        self.riotdb.gd = gd
        self.advisor.__dict__ = fresh.__dict__      # 一次换掉，识别线程不会看到半空的状态
        self.gd = gd
        self.last_sig = None
        n = clean_old_cache(data_versions(gd, stats))
        self.q.put(("data", msg + (tr('（清理旧缓存 {0} 个）').format(n) if n else "")))

    def champ_select_step(self):
        """选英雄阶段：读客户端的选人资讯（你的英雄、备选席、队友），给可换的英雄打分"""
        if isinstance(self.source, MockGame):
            return None
        now = time.time()
        if now - getattr(self, "_cs_t", 0) < 0.9:
            return getattr(self, "_cs_last", None) and ("status", tr("选英雄中"))
        self._cs_t = now
        cred = getattr(self, "_lcu_cred", None)
        if cred is None:
            self.find_lcu_async()                         # 背景找客户端连接资讯（不卡住这里）
            return None
        try:
            sess = lcu_get("/lol-champ-select/v1/session", cred, timeout=3)
        except urllib.error.HTTPError:
            self._cs_last = None                         # 404＝没在选英雄
            return None
        except Exception:  # noqa                         客户端关了 / 换了端口
            self._lcu_cred, self._cs_last = None, None
            return None
        try:     # 客户端直接告诉你「你现在的英雄」：分配英雄那一下 session 里还读不到时靠它
            cur = lcu_get("/lol-champ-select/v1/current-champion", cred, timeout=2)
            if isinstance(cur, int) and cur > 0 and isinstance(sess, dict):
                sess["_current"] = cur
        except Exception:  # noqa
            pass
        if isinstance(sess, dict):
            raw_sig = json.dumps(sess, sort_keys=True, default=str)[:200000]
            if raw_sig != getattr(self, "_cs_dump", None):      # 存一份选人资料（只在本机），方便查问题
                self._cs_dump = raw_sig
                try:
                    with open(os.path.join(APP_DIR, "last_champselect.json"), "w", encoding="utf-8") as f:
                        f.write(raw_sig)
                except OSError:
                    pass
        payload = self.champ_select_payload(sess)
        if payload is None:
            return None
        sig = (tuple(payload["cand_ids"]), tuple(payload["team_ids"]), self.stats_dirty)
        with self.lock:
            self.stats_dirty = False
        if sig == getattr(self, "_cs_sig", None):
            return ("status", tr("选英雄中"))
        self._cs_sig = sig
        self._cs_last = payload
        return ("select", payload)

    def find_lcu_async(self):
        """在背景找游戏客户端的连接资讯（读 lockfile 或进程参数，可能要 1~3 秒）"""
        if getattr(self, "_lcu_finding", False) or time.time() - getattr(self, "_lcu_try", 0) < 10:
            return
        self._lcu_finding, self._lcu_try = True, time.time()

        def run():
            try:
                self._lcu_cred = lcu_credentials()
            finally:
                self._lcu_finding = False
        threading.Thread(target=run, daemon=True).start()

    def champ_select_payload(self, sess):
        by_key = {str(c.get("key")): c["id"] for c in self.gd.champs.values()}
        cell = sess.get("localPlayerCellId")
        mine, team = None, []
        for m in sess.get("myTeam", []) or []:
            cid = by_key.get(str(m.get("championId") or m.get("championPickIntent") or 0))
            if m.get("cellId") == cell:
                mine = cid
            elif cid:
                team.append(cid)
        if mine is None and sess.get("_current"):  # 客户端回报的「你现在的英雄」
            mine = by_key.get(str(sess["_current"]))
        if mine is None:                        # 刚分配英雄的那一下 myTeam 可能还是 0：改看选人动作
            for grp in sess.get("actions") or []:
                for a in grp if isinstance(grp, list) else []:
                    if a.get("actorCellId") == cell and a.get("championId"):
                        mine = by_key.get(str(a["championId"])) or mine
        bench = sess.get("benchChampions")
        bench_ids = [b.get("championId") for b in bench] if isinstance(bench, list) and bench and isinstance(bench[0], dict) \
            else (sess.get("benchChampionIds") or bench or [])
        bench_c = [by_key.get(str(b)) for b in bench_ids]
        for k, v in sess.items():               # 其他放英雄的栏位（新模式的英雄卡片之类）
            if k in ("myTeam", "theirTeam", "benchChampions", "benchChampionIds", "actions", "bans", "trades",
                     "swaps", "pickOrderSwaps", "positionSwaps") or "champion" not in k.lower() or not isinstance(v, list):
                continue
            for x in v:
                cid = x.get("championId") if isinstance(x, dict) else x
                if isinstance(cid, int) and cid > 0:
                    bench_c.append(by_key.get(str(cid)))
        cands = list(dict.fromkeys(([mine] if mine else []) + [b for b in bench_c if b and b != mine]))
        if not cands:
            return None
        ranked, needs = self.advisor.rank_champions(cands, team, mine)
        return {"cands": ranked, "cand_ids": cands, "team_ids": team, "needs": needs, "mine": mine,
                "bench_enabled": bool(sess.get("benchEnabled", True))}

    def track_game(self, raw, state, rec):
        """记下这局的英雄、成品装备、已选增幅、三选一出现过的增幅；读到 GameEnd 就存起来"""
        mode, map_id, me = state[0], state[1], state[2]
        if self._ended or me is None or mode_kind(mode, map_id) != "aram":
            return
        g = self.cur_game
        champ = (self.gd.champ(me.cid) or {}).get("id", me.cid)
        if g is None or g["champ"] != champ:
            g = self.cur_game = {"champ": champ, "t": time.strftime("%Y-%m-%d %H:%M"), "ts": time.time(), "items": [],
                                 "augs": [], "offered": [], "win": None, "len": 0}
        g["len"] = int(me.game_time)
        items = [i for i in me.items if self.gd.is_completed(i)]
        # 复盘用：新买的成品装备，是不是在「买之前那次」推荐的前 3 名里
        top = getattr(self, "_last_top", None)
        follow = g.setdefault("item_follow", [])
        known = {i for i, _ in follow}
        for i in items:
            if i not in known and i not in g["items"] and top is not None:
                follow.append((i, i in top))
        g["items"] = items
        for i in items:
            if i not in {x for x, _ in follow} and top is None:
                follow.append((i, None))              # 这局刚开始就有的（没有推荐可比）
        nonboots = [x["id"] for x in rec.get("items", []) if not x.get("boots")][:3]
        boots = [x["id"] for x in rec.get("items", []) if x.get("boots")]
        self._last_top = set(nonboots + boots)
        # 增幅：选的是不是 ★ 那张
        offer = getattr(self, "_last_offer", None)
        for n in rec.get("my_augs", []):
            if n not in g["augs"]:
                g["augs"].append(n)
                if offer and n in offer[0]:
                    g.setdefault("aug_follow", []).append((n, n == offer[1]))
        if rec.get("cand_mode") and rec.get("augs"):
            names = [a["name"] for a in rec["augs"]]
            self._last_offer = (names, names[0])
            for a in names:
                if a not in g["offered"]:
                    g["offered"].append(a)

    def check_game_end(self, raw):
        """每次读取都看有没有 GameEnd 事件（不管推荐有没有变化）"""
        if self._ended or self.cur_game is None:
            return
        for ev in ((raw.get("events") or {}).get("Events") or []):
            if ev.get("EventName") == "GameEnd":
                self.finish_game(str(ev.get("Result", "")).lower().startswith("win"))
                self._ended = True
                break

    def finish_game(self, win):
        g, self.cur_game = self.cur_game, None
        self._last_top = self._last_offer = None
        if g and g["len"] >= 300:           # 打了 5 分钟以上的才算（重开、掉线不记）
            g["win"] = win
            self.habits.add_game(g)
            self.q.put(("review", self.review(g)))
            self.import_history_async(delay=60)    # 客户端结算后会更新对局记录，补上编号以免重复

    def review(self, g):
        """赛后复盘的一段文字"""
        gd = self.gd
        f = [x for x in g.get("item_follow", []) if x[1] is not None]
        af = g.get("aug_follow", [])
        hp = self.habits.profile(g["champ"])
        res = tr("赢了") if g.get("win") else tr("输了") if g.get("win") is False else tr("结束")
        head = tr('复盘：{0}{1} · {2} 分钟').format(gd.champ_name(g["champ"]), res, g["len"] // 60)
        parts = []
        if f:
            parts.append(tr('出装 {0}/{1} 件照推荐').format(sum(1 for _, ok in f if ok), len(f)))
        if af:
            parts.append(tr('增幅 {0}/{1} 次选了 ★').format(sum(1 for _, ok in af if ok), len(af)))
        if hp["games"]:
            parts.append(tr('这个英雄 {0} 局 {1} 胜').format(hp["games"], hp["wins"]))
        off = [gd.item_name(i) for i, ok in f if ok is False]
        detail = tr('没照推荐的：{0}').format(tr("、").join(off)) if off else ""
        return {"text": head + (" · " + " · ".join(parts) if parts else ""), "detail": detail,
                "items": [gd.item_name(i) for i in g.get("items", [])], "augs": g.get("augs", [])}

    def import_history_async(self, delay=0, manual=False):
        """背景从游戏客户端读取你的历史对局（只读）"""
        if getattr(self, "_importing", False) or isinstance(self.source, MockGame):
            return
        self._importing = True

        def run():
            try:
                time.sleep(delay)
                n, msg = import_client_history(self.gd, self.habits)
                if n:
                    for g in self.habits.games:           # 自己记的复盘资料搬到客户端那份上
                        if g.get("gameId"):
                            continue
                        for c in self.habits.games:
                            if c.get("gameId") and c["champ"] == g["champ"] and abs((c.get("ts") or 0) - (g.get("ts") or 0)) < 3600:
                                for k in ("item_follow", "aug_follow"):
                                    if g.get(k) and not c.get(k):
                                        c[k] = g[k]
                    # 本程序自己记的、没有 gameId 的同一局：留客户端那份（有准确输赢和增幅）
                    self.habits.games = [g for g in self.habits.games if g.get("gameId") or
                                         not any(c.get("gameId") and c["champ"] == g["champ"] and
                                                 abs((c.get("ts") or 0) - (g.get("ts") or 0)) < 3600
                                                 for c in self.habits.games)]
                    self.habits._cache.clear()
                    self.last_sig = None
                    self.wake.set()
                if n or manual:
                    self.q.put(("data", msg))
            except Exception as e:  # noqa
                if manual:
                    self.q.put(("data", tr('读取客户端对局记录失败：{0}').format(e)))
            finally:
                self._importing = False
        threading.Thread(target=run, daemon=True).start()

    def set_manual(self, key, text):
        vals = [x.strip() for x in re.split(r"[,，、;；\s]+", text) if x.strip()]
        with self.lock:
            if key == "mine" and self.manual.get("picked"):
                # 输入框里显示的是「手动 + 自动记录」的全部：内容没变就什么都不动；改了才以输入框为准
                if vals == self.manual.get("mine", []) + self.manual["picked"]:
                    return
                self.manual["picked"] = []
                self.manual_dirty = True
            if self.manual.get(key) != vals:
                self.manual[key] = vals
                self.manual_dirty = True
                self.wake.set()

    def add_pick(self, name):
        with self.lock:
            if name in self.manual.get("picked", []) or name in self.manual.get("mine", []):
                return
            self.manual.setdefault("picked", []).append(name)
            self.manual_dirty = "picked:" + name
        self.wake.set()

    def set_auto(self, offers):
        """offers: [(name, desc)]，空列表表示三选一界面消失"""
        vals = [f"{n}|{d}" for n, d in offers]
        if vals:
            self._auto_t = time.time()           # 识别又看到了三选一（就算没变也更新时间）
        with self.lock:
            old = [s.split("|", 1)[0] for s in self.manual["auto"]]
            new = [n for n, _ in offers]
            if same_offer(old, new) or (not old and not new):
                return
            self.manual["auto"] = vals
            self.manual_dirty = ("auto_reroll" if old and vals else "auto_on" if vals else "auto_off")
        self.wake.set()

    def step(self):
        if self.pending_data and (not self.connected or self.last_state is None):
            self.apply_pending()           # 只在对局外 / 新一局开始前换数据
        try:
            # 只是手动输入 / 识别到三选一而被叫醒、刚刚才读过对局：直接用刚才的数据，省一次读取
            if self.manual_dirty and self._raw is not None and time.time() - self._raw_t < 1.5:
                raw = self._raw
            else:
                raw = self.source.fetch()
                self._raw, self._raw_t = raw, time.time()
            state = parse_live(raw)
            ap = raw.get("activePlayer") or {}
            self.my_riot_id = ap.get("riotId") or self.__dict__.get("my_riot_id", "")
        except Exception:
            self.fails += 1
            self._raw = None
            if self.fails < 3 and self.connected:      # 游戏卡顿读不到一两次，不当成对局结束
                return ("status", tr("监控中"))
            self.finish_game(None)                      # 对局结束（没读到输赢）
            self._ended = False
            self.last_sig = None
            self.last_state = None
            self.connected = False
            sel = self.champ_select_step()              # 不在对局中：看看是不是在选英雄
            return sel or ("status", tr("等待对局…"))
        self.fails = 0
        if not self.connected or self.last_state is None:
            self.advisor._ema_cid = None                # 新的一局：平滑从头开始
            self.advisor._eaug_seen = {}
            self._dumped = False
        self.connected = True
        if state[2] is None:
            return ("status", tr("已连接，等待玩家数据…"))
        self.check_game_end(raw)
        if state[2].game_time > 420 and not getattr(self, "_dumped", False) and not isinstance(self.source, MockGame):
            self._dumped = True             # 存一份这局的游戏资料（只在本机），方便查游戏有没有提供敌方增幅
            try:
                with open(os.path.join(APP_DIR, "last_live.json"), "w", encoding="utf-8") as f:
                    json.dump(raw, f, ensure_ascii=False)
            except OSError:
                pass
        # 三选一超过 20 秒没再被识别看到（画面早就关了、但没确认到关闭）：自动清掉，免得一直停在增幅页
        if self.manual.get("auto") and time.time() - getattr(self, "_auto_t", 0) > 20:
            self.set_auto([])
            with self.lock:
                self.manual_dirty = "auto_off"
        with self.lock:
            manual = {k: list(v) for k, v in self.manual.items()}
            dirty, self.manual_dirty = self.manual_dirty, False
        sig = signature(state, manual)
        lsig = live_signature(state)
        with self.lock:
            stats_new, self.stats_dirty = self.stats_dirty, False
        if sig == self.last_sig and lsig == getattr(self, "last_lsig", None) and not stats_new:
            return ("status", tr("监控中"))
        quiet = sig == self.last_sig and not stats_new  # 只有阵亡/击杀/血量变化：更新战术，不弹出窗口
        changes = (describe_live(self.gd, self.last_state, state) if quiet
                   else describe_changes(self.gd, self.last_state, state, dirty))
        if stats_new:
            changes = [tr("已载入网上胜率数据")] + [c for c in changes if c != tr("阵容信息变化")]
            self.advisor._ema_cid = None     # 新数据进来：重新排序，不沿用旧的平滑结果
        self.last_sig, self.last_lsig, self.last_state = sig, lsig, state
        rec = self.advisor.analyze(state, manual)
        self.track_game(raw, state, rec)
        rec["changes"] = changes
        rec["quiet"] = quiet
        rec["time"] = time.strftime("%H:%M:%S")
        self.history.append(rec)
        self.history = self.history[-30:]
        return ("rec", rec)

    def run(self, stop):
        if not isinstance(self.source, MockGame):
            self.find_lcu_async()                # 一启动就先找好客户端连接，进选英雄时马上能读
        self.import_history_async(delay=3)       # 启动时先从客户端读一次历史对局
        if not isinstance(self.source, MockGame):
            threading.Thread(target=self.riotdb.run, args=(self, stop), daemon=True).start()
        while not stop.is_set():
            try:
                self.q.put(self.step())
            except Exception as e:  # 推荐演算法异常不应让挂件崩溃
                self.q.put(("status", tr('分析出错：{0}').format(e)))
            # 选英雄阶段每秒看一次（换人、重骰马上更新）；平时按设定间隔
            self.wake.wait(1.0 if getattr(self, "_cs_last", None) else self.interval)  # 手动输入 / 识别到新增幅时会被立即唤醒
            self.wake.clear()



