# 你的习惯（只存在本机 %USERPROFILE%\.lol_haidou_helper\habits.json，不上传）
# 每局海斗结束时记下：英雄、出了哪些成品装备、拿了哪些增幅、三选一里出现过哪些增幅、输赢。
# 推荐时偏向你熟悉、而且你用了赢得多的装备 / 增幅（加分有上限，网上数据仍是主要依据）。
# --------------------------------------------------------------------------------------
class HabitStore:
    MAX_GAMES = 400

    def __init__(self, path=None):
        self.path = path or os.path.join(APP_DIR, "habits.json")
        data = read_json(self.path) if os.path.exists(self.path) else None
        self.games = data.get("games", []) if isinstance(data, dict) else []
        self.enabled = load_ui_cfg().get("habits", True)
        self._cache = {}

    def add_game(self, g):
        if not self.enabled or not g.get("champ"):
            return
        self.games.append(g)
        self.games = self.games[-self.MAX_GAMES:]
        self._cache.clear()
        try:
            write_json(self.path, {"version": 1, "games": self.games})
        except OSError:
            pass

    def import_games(self, games):
        """导入客户端里的历史对局（按 gameId 去重），回传新增几局"""
        have = {g.get("gameId") for g in self.games if g.get("gameId")}
        new = [g for g in games if g.get("gameId") and g["gameId"] not in have and g.get("champ")]
        if not new or not self.enabled:
            return 0
        self.games = sorted(self.games + new, key=lambda g: g.get("ts", 0) or 0)[-self.MAX_GAMES:]
        self._cache.clear()
        try:
            write_json(self.path, {"version": 1, "games": self.games})
        except OSError:
            pass
        return len(new)

    def clear(self):
        self.games = []
        self._cache.clear()
        try:
            write_json(self.path, {"version": 1, "games": []})
        except OSError:
            pass

    def report(self, gd):
        """战绩页的文字：总体、照推荐 vs 没照推荐、各英雄、最近几局"""
        games = [g for g in self.games if g.get("champ")]
        if not games:
            return tr("还没有记录。打几局海斗，或在「我的习惯」里从游戏客户端导入历史对局。")
        dec = [g for g in games if g.get("win") is not None]

        def wr(lst):
            d = [g for g in lst if g.get("win") is not None]
            return (100 * sum(1 for g in d if g["win"]) / len(d)) if d else None

        def fmt(w):
            return "—" if w is None else f"{w:.0f}%"
        lines = [tr('总计 {0} 局，胜率 {1}').format(len(games), fmt(wr(dec)))]
        # 照推荐出装的局 vs 没照的局
        follow, other = [], []
        for g in dec:
            f = [x for x in g.get("item_follow", []) if x[1] is not None]
            if len(f) >= 2:
                (follow if sum(1 for x in f if x[1]) / len(f) >= 0.6 else other).append(g)
        if follow or other:
            lines.append(tr('照推荐出装（≥60% 的装备）：{0} 局，胜率 {1}　｜　没照：{2} 局，胜率 {3}').format(
                len(follow), fmt(wr(follow)), len(other), fmt(wr(other))))
        lines.append("")
        lines.append(tr("英雄            局数  胜率   常出装备"))
        champs = Counter(g["champ"] for g in games)
        for champ, n in champs.most_common(15):
            prof = self.profile(champ)
            top = sorted(prof["items"].items(), key=lambda x: -x[1][0])[:3]
            name = gd.champ_name(champ)
            lines.append(f"{name:<8}{n:>6}  {fmt(wr([g for g in games if g['champ'] == champ])):>5}   " +
                         tr("、").join(gd.item_name(i) for i, _ in top))
        lines.append("")
        lines.append(tr("最近 10 局"))
        for g in sorted(games, key=lambda g: g.get("t", ""))[-10:][::-1]:
            res = tr("胜") if g.get("win") else tr("负") if g.get("win") is False else "?"
            items = tr("、").join(gd.item_name(i) for i in g.get("items", [])[:6])
            lines.append(f"{g.get('t', '')[:16]}  {res}  {gd.champ_name(g['champ'])}  {items}")
        return "\n".join(lines)

    def profile(self, champ):
        """这个英雄的个人统计：局数、胜场、每件装备 / 每个增幅的（次数, 赢的次数），增幅出现次数"""
        champ = str(champ or "").lower()
        if champ in self._cache:
            return self._cache[champ]
        games = [g for g in self.games if str(g.get("champ", "")).lower() == champ]
        prof = {"games": len(games), "wins": sum(1 for g in games if g.get("win")),
                "decided": sum(1 for g in games if g.get("win") is not None),
                "items": {}, "augs": {}, "offered": {}}
        for g in games:
            w = 1 if g.get("win") else 0
            for i in set(g.get("items", [])):
                c = prof["items"].setdefault(int(i), [0, 0])
                c[0] += 1
                c[1] += w
            for a in set(g.get("augs", [])):
                c = prof["augs"].setdefault(a, [0, 0])
                c[0] += 1
                c[1] += w
            for a in set(g.get("offered", [])):
                prof["offered"][a] = prof["offered"].get(a, 0) + 1
        self._cache[champ] = prof
        return prof


def habit_bonus(cnt, wins, games, all_wins, decided, weight):
    """个人习惯加分 = weight × 熟悉度 × 战绩修正
         熟悉度 = √(min(次数 / 局数, 60%) / 60%)
         战绩修正 = 1 + clamp(5 × 收缩后的胜率差, −0.5, +0.5)，收缩：差 × n / (n + 5)
       这个英雄打不到 2 局不加分。"""
    if games < 2 or cnt <= 0:
        return 0.0
    fam = math.sqrt(min(cnt / games, 0.6) / 0.6)
    adj = 1.0
    if decided >= 2:
        base = (all_wins + 1) / (decided + 2)
        mine = (wins + 1) / (cnt + 2)
        adj = 1 + max(-0.5, min(0.5, 5 * (mine - base) * cnt / (cnt + 5)))
    return weight * fam * adj


