def load_all(lang, bracket="all", use_stats=True, log=print, force=False):
    """下载（或读缓存）全部数据：游戏装备/英雄/增幅 + 海斗胜率、商店、增幅池、平衡调整"""
    gd = GameData.load(lang, log=log)
    stats = None
    if use_stats:
        stats = StatsProvider(lang, log=log)
        stats.dataset = bracket
        stats.load_version(force=force)
        extra = stats.load_augments()
        allow = stats.load_items() or set()        # 海斗商店清单：就算增幅资料没下载到也要用
        if extra:
            gd.merge_augments(extra)
            stats.load_spell_names()
            stats.load_balance()
            stats.game_version = ".".join(str(gd.version).split(".")[:2])
            log(tr('[胜率] {0}：海斗增幅 {1} 个，商店成品装备 {2} 件').format(stats.label(), len(extra), len(allow)))
    gd.add_english_names(log=log)      # 英文客户端的卡名也认得（按编号对应）
    try:
        n = gd.add_arammayhem(load_arammayhem(log=log))
        if n:
            log(tr('[arammayhem] 对上 {0} 个增幅（多语言名称、国服选取率、推荐组合）').format(n))
    except Exception as e:  # noqa   第二个数据源出问题不影响主要功能
        log(tr('[arammayhem] 读取失败：{0}').format(e))
    return gd, stats


def data_versions(gd, stats):
    sv = (stats.version or {}) if stats else {}
    return (str(gd.version), sv.get("dataPath", ""), sv.get("resourcePath", ""))


def clean_old_cache(keep):
    """删掉旧版本的缓存文件（每个版本几十 MB，不清会越积越多）"""
    game_ver, data_path, res_path = keep
    dp, rp = data_path.replace("/", "_"), res_path.replace("/", "_")
    removed = 0
    try:
        for fn in os.listdir(APP_DIR):
            if (fn.startswith("kit_") and not fn.startswith(f"kit_{game_ver}_")) or \
                    (fn.startswith("ver_") and not fn.startswith(f"ver_{game_ver}_")):
                os.remove(os.path.join(APP_DIR, fn))
                removed += 1
        kd = os.path.join(APP_DIR, "aramkit")
        for fn in os.listdir(kd) if os.path.isdir(kd) else []:
            if fn == "versions.json":
                continue
            if (dp and fn.startswith(("champ_", "sa_")) and dp not in fn) or \
                    (rp and fn.startswith(("aug_", "items_", "champs_", "ss_")) and rp not in fn):
                os.remove(os.path.join(kd, fn))
                removed += 1
    except OSError:
        pass
    return removed


class DataUpdater:
    """背景检查新版本：不在对局中时每 30 分钟一次、每局结束时一次、也可手动。
    有新版本就在背景下载好，等到不在对局中（或新一局开始前）再换上，不会打断正在打的一局。"""
    EVERY = 30 * 60

    def __init__(self, engine, lang, use_stats=True):
        self.engine, self.lang, self.use_stats = engine, lang, use_stats
        self.last_check = time.time()          # 启动时刚载入过
        self.now = threading.Event()
        self.busy = False
        self.last_result = ""
        self.app_new = None
        self.last_app_check = time.time() - 6 * 3600 + 15    # 启动 15 秒后查一次程序新版本

    def check_app(self, manual=False):
        self.last_app_check = time.time()
        m, err = check_app_version()
        if m:
            self.app_new = m
            self.engine.q.put(("appupd", m))
        elif manual:
            self.engine.q.put(("data", tr("检查程序新版本失败") if err else tr('程序已是最新 v{0}').format(APP_VERSION)))

    def check_now(self):
        self.now.set()

    def upgrade(self):
        """一键更新（背景执行）"""
        q = self.engine.q
        m = self.app_new
        if not m:
            return
        try:
            q.put(("data", tr("更新中…")))
            changed = install_update(m, log=lambda x: q.put(("data", x)))
            q.put(("upgraded", tr("已更新到 v{0}，重新打开海斗助手生效").format(m.get("version")) if changed
                   else tr("已是最新文件，重新打开即可")))
        except Exception as e:  # noqa
            q.put(("data", tr("更新失败：{0}").format(e)))

    def _remote_versions(self):
        game = http_json(DDRAGON + "/api/versions.json", timeout=10)[0]
        dp = rp = ""
        if self.use_stats:
            v = http_json(f"{ARAMKIT}/data/versions.json", timeout=15)
            cur = next((x for x in v.get("versions", []) if x.get("version") == v.get("latest")),
                       (v.get("versions") or [{}])[0])
            dp, rp = cur.get("dataPath", ""), cur.get("resourcePath", "")
        return game, dp, rp

    def check(self, manual=False):
        eng = self.engine
        self.busy = True
        try:
            cur = data_versions(eng.gd, eng.advisor.stats)
            try:
                remote = self._remote_versions()
            except Exception:  # noqa
                self.last_result = tr("检查更新失败（连不上数据网站）")
                if manual:
                    eng.q.put(("data", self.last_result))
                return
            changed = [n for n, a, b in zip((tr("游戏数据"), tr("海斗胜率"), tr("海斗资料")), cur, remote) if b and a != b]
            if not changed:
                self.last_result = tr("已是最新 ") + ".".join(cur[0].split(".")[:2])
                if manual:
                    eng.q.put(("data", self.last_result))
                return
            eng.q.put(("data", tr("发现新版本，背景下载中…")))
            bracket = eng.advisor.stats.dataset if eng.advisor.stats else "all"
            gd, stats = load_all(self.lang, bracket, self.use_stats, log=lambda m: None, force=True)
            new = data_versions(gd, stats)
            if new == cur:
                self.last_result = tr("已是最新 ") + ".".join(cur[0].split(".")[:2])
                return
            what = []
            if new[0] != cur[0]:
                what.append(tr('游戏 {0} → {1}').format(cur[0], new[0]))
            if new[1] != cur[1] and stats:
                what.append(tr('海斗胜率 {0}（{1}）').format(stats.version.get('version', ''), stats.version.get('dataDate', '')))
            elif new[2] != cur[2]:
                what.append(tr("海斗增幅/装备/平衡调整"))
            eng.pending_data = (gd, stats, tr("数据已更新：") + tr("，").join(what))
            eng.wake.set()
        finally:
            self.last_check = time.time()
            self.busy = False

    def run(self, stop):
        was_connected = False
        while not stop.is_set():
            manual = self.now.wait(20)
            self.now.clear()
            conn = self.engine.connected
            game_over = was_connected and not conn
            was_connected = conn
            due = time.time() - self.last_check > self.EVERY
            if manual or (not conn and (game_over or due)):   # 对局中不检查，不占网络
                try:
                    self.check(manual)
                except Exception as e:  # noqa
                    self.engine.q.put(("data", tr('更新出错：{0}').format(e)))
            if manual or (not conn and time.time() - self.last_app_check > 6 * 3600):
                try:
                    self.check_app(manual)
                except Exception:  # noqa
                    pass


def start_updater(engine, lang, use_stats, stop):
    up = DataUpdater(engine, lang, use_stats)
    engine.updater = up
    threading.Thread(target=up.run, args=(stop,), daemon=True).start()
    return up

