def load_ui_cfg():
    try:
        with open(os.path.join(APP_DIR, "ui.json"), encoding="utf-8") as f:
            return json.load(f)
    except Exception:  # noqa
        return {}


def save_ui_cfg(cfg):
    try:
        os.makedirs(APP_DIR, exist_ok=True)
        with open(os.path.join(APP_DIR, "ui.json"), "w", encoding="utf-8") as f:
            json.dump(cfg, f)
    except Exception:  # noqa
        pass


def run_overlay(engine, alpha=0.92, scanner=None, scale=None):
    """紧凑悬浮窗：出装 / 增幅 / 玩法 三个分页，一次只看一页；平时收成一行。"""
    import tkinter as tk
    import tkinter.font as tkfont

    # ---------- 配色 ----------
    BG, CARD, CARD_HI, HEAD = "#0f1218", "#161b25", "#1d2431", "#0a0d12"
    FG, SUB, DIM, GOLD = "#e6e9ef", "#8a93a6", "#5b6477", "#c8aa6e"
    GREEN, YELLOW, GREY, ORANGE = "#3ddc84", "#f5c542", "#7b8497", "#ff8a3d"
    FAMILY = "Microsoft YaHei UI" if sys.platform.startswith("win") else "Noto Sans CJK SC"

    def score_color(s):
        return GREEN if s >= 80 else YELLOW if s >= 65 else GREY

    cfg = load_ui_cfg()
    root = tk.Tk()
    root.title(tr("海斗助手"))
    root.overrideredirect(True)
    root.attributes("-topmost", True)
    try:
        root.attributes("-alpha", alpha)
    except tk.TclError:
        pass
    root.configure(bg=BG, highlightthickness=1, highlightbackground="#2a3140")
    dpi = max(1.0, root.winfo_fpixels("1i") / 96.0)
    sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
    st = {"k": scale or cfg.get("scale", 1.0), "x": cfg.get("x"), "y": cfg.get("y", int(sh * 0.22)),
          "pinned": False, "expanded": True, "hold_until": 0.0, "inside_since": None, "left_at": 0.0, "last_key": None,
          "tab": "items", "user_tab": False, "tab_before_cand": None}
    if st["x"] is None:
        st["x"] = sw - int(300 * dpi * st["k"]) - 12
    st["x"], st["y"] = min(max(0, st["x"]), sw - 120), min(max(0, st["y"]), sh - 60)

    BASE = {"title": (10, "bold"), "tab": (9, "bold"), "name": (10, "bold"), "score": (11, "bold"),
            "small": (8, "normal"), "tip": (9, "normal"), "icon": (10, "normal")}
    F = {k: tkfont.Font(family=FAMILY, size=v, weight=w) for k, (v, w) in BASE.items()}
    wraps = []

    def W():
        return int(300 * dpi * st["k"])

    def fit():
        root.update_idletasks()
        need = root.winfo_reqheight()
        root.geometry(f"{W()}x{min(need, sh - st['y'] - 8)}+{st['x']}+{st['y']}")

    def persist():
        c = load_ui_cfg()
        c.update({"scale": st["k"], "x": st["x"], "y": st["y"]})
        save_ui_cfg(c)

    def set_scale(k):
        st["k"] = k
        for key, (v, w) in BASE.items():
            F[key].configure(size=max(6, round(v * k)))
        for lb in wraps:
            lb.config(wraplength=W() - int(28 * dpi))
        fit()
        persist()

    # ---------- 小工具：悬停提示 ----------
    tip_win = {"w": None}

    def kill_tip():
        if tip_win["w"] is not None:
            try:
                tip_win["w"].destroy()
            except tk.TclError:
                pass
            tip_win["w"] = None

    def hover(widget, text_fn):
        def enter(e):
            kill_tip()
            text = text_fn()
            if not text:
                return
            tw = tk.Toplevel(root)
            tw.overrideredirect(True)
            tw.attributes("-topmost", True)
            tk.Label(tw, text=text, bg="#232b3a", fg=FG, font=F["small"], justify="left",
                     wraplength=int(260 * dpi * st["k"]), padx=8, pady=6).pack()
            tw.update_idletasks()
            x = root.winfo_rootx() - tw.winfo_reqwidth() - 6
            if x < 0:
                x = root.winfo_rootx() + root.winfo_width() + 6
            tw.geometry(f"+{x}+{e.y_root - 10}")
            tip_win["w"] = tw

        def leave(_e):
            kill_tip()
        widget.bind("<Enter>", enter, add="+")
        widget.bind("<Leave>", leave, add="+")

    # ---------- 标题栏 ----------
    header = tk.Frame(root, bg=HEAD)
    header.pack(fill="x")
    dot = tk.Label(header, text="●", bg=HEAD, fg=GREY, font=F["small"])
    dot.pack(side="left", padx=(8, 2), pady=5)
    title = tk.Label(header, text=tr("海斗助手"), bg=HEAD, fg=GOLD, font=F["title"])
    title.pack(side="left")
    status = tk.Label(header, text="", bg=HEAD, fg=DIM, font=F["small"])
    status.pack(side="left", padx=6)

    def set_status(text):
        """没有别的消息时，标题栏显示新版本提醒（金色，可点）"""
        if not text and st.get("app_new"):
            status.config(text=tr('⇪ 新版 v{0}').format(st['app_new'].get('version', '')), fg=GOLD, cursor="hand2")
        else:
            status.config(text=text, fg=DIM, cursor="")

    def open_download(_e=None):
        """点「⇪ 新版」：直接从 GitHub 更新（没有文件清单的旧版本就打开下载页）"""
        m = st.get("app_new")
        up = getattr(engine, "updater", None)
        if not m or st.get("upgrading"):
            return
        if m.get("files") and up is not None:
            st["upgrading"] = True
            st["status_hold"] = time.time() + 120
            set_status(tr("更新中…"))
            threading.Thread(target=up.upgrade, daemon=True).start()
        else:
            import webbrowser
            webbrowser.open(REPO_URL)
    status.bind("<Button-1>", open_download, add="+")
    hover(status, lambda: (tr("海斗助手 v{} 已发布（你现在是 v{}）\n").format(st["app_new"].get("version"), APP_VERSION) +
                           "\n".join("· " + x for x in st["app_new"].get("notes", [])[:6]) +
                           tr("\n点一下直接更新（从 GitHub 下载并校验），重新打开生效")) if st.get("app_new") else "")

    def hbtn(text, cmd, fg=SUB, bg=HEAD):
        b = tk.Label(header, text=text, bg=bg, fg=fg, font=F["small"], padx=7, pady=3, cursor="hand2")
        b.pack(side="right", padx=(0, 2))
        b.bind("<Button-1>", lambda e: cmd())
        b.bind("<Enter>", lambda e: b.config(fg=FG), add="+")
        b.bind("<Leave>", lambda e: b.config(fg=fg), add="+")
        return b

    menu_btn = hbtn("⋯", lambda: open_menu())
    pin_btn = hbtn("📌", lambda: toggle_pin(), fg=GOLD if st["pinned"] else SUB)
    hk = getattr(getattr(engine, "hotkey", None), "name", "")
    hbtn(tr('识别 {0}').format(hk).strip(), lambda: force_scan(), fg=FG, bg="#2b3a57")

    drag = {}

    def start_drag(e):
        drag["x"], drag["y"] = e.x_root - root.winfo_x(), e.y_root - root.winfo_y()

    def do_drag(e):
        st["x"], st["y"] = e.x_root - drag["x"], e.y_root - drag["y"]
        root.geometry(f"+{st['x']}+{st['y']}")
    for w in (header, title, status, dot):
        w.bind("<ButtonPress-1>", start_drag, add="+")
        w.bind("<B1-Motion>", do_drag)
        w.bind("<ButtonRelease-1>", lambda e: persist())

    # ---------- 单行模式 ----------
    mini = tk.Label(root, text=tr("等待对局…"), bg=BG, fg=FG, font=F["tip"], anchor="w", justify="left", padx=8, pady=5)
    wraps.append(mini)

    # ---------- 展开内容 ----------
    body = tk.Frame(root, bg=BG)
    body.pack(fill="both", expand=True)
    summary = tk.Label(body, text="", bg=BG, fg=SUB, font=F["small"], anchor="w", justify="left", padx=8)
    summary.pack(fill="x", pady=(5, 0))
    wraps.append(summary)
    alert = tk.Label(body, text="", bg="#3a2412", fg=ORANGE, font=F["tip"], anchor="w", justify="left", padx=8, pady=3)
    wraps.append(alert)
    # 战况条：连招 / 战局 / 威胁 / 玩法（一直显示、即时更新）
    st["brief"] = load_ui_cfg().get("brief", True)
    brief_box = tk.Frame(body, bg=CARD, padx=8, pady=4)
    brief_rows = []
    for _ in range(5):
        lb = tk.Label(brief_box, text="", bg=CARD, fg=GOLD, font=F["small"], anchor="w")
        tx = tk.Label(brief_box, text="", bg=CARD, fg=FG, font=F["tip"], anchor="w", justify="left")
        brief_rows.append((lb, tx))
        wraps.append(tx)

    def show_brief(items):
        if not st["brief"] or not items:
            brief_box.pack_forget()
            return False
        for i, (lb, tx) in enumerate(brief_rows):
            if i < len(items):
                label, text, hot = items[i]
                lb.config(text=label)
                tx.config(text=text, fg=ORANGE if hot else FG)
                lb.grid(row=i, column=0, sticky="nw", padx=(0, 8))
                tx.grid(row=i, column=1, sticky="w")
            else:
                lb.grid_forget()
                tx.grid_forget()
        brief_box.pack(fill="x", padx=8, pady=(5, 0), before=tabs_bar)
        return True

    tabs_bar = tk.Frame(body, bg=BG)
    tabs_bar.pack(fill="x", padx=6, pady=(6, 2))
    tab_btns = {}

    def select_tab(name, user=False):
        st["tab"] = name
        if user:
            st["user_tab"] = True
            st["tab_before_cand"] = None           # 你自己选了分页：三选一结束后不用切回
        for k, (lb, ul) in tab_btns.items():
            on = k == name
            lb.config(fg=FG if on else DIM)
            ul.config(bg=GOLD if on else BG)
        for k, fr in pages.items():
            fr.pack_forget()
        pages[name].pack(fill="x", padx=6, pady=(4, 4), before=footer)
        fit()

    for key, text in (("items", tr("出装")), ("augs", tr("增幅")), ("guide", tr("玩法"))):
        holder = tk.Frame(tabs_bar, bg=BG)
        holder.pack(side="left", padx=(2, 10))
        lb = tk.Label(holder, text=text, bg=BG, fg=DIM, font=F["tab"], cursor="hand2")
        lb.pack()
        ul = tk.Frame(holder, bg=BG, height=2)
        ul.pack(fill="x")
        lb.bind("<Button-1>", lambda e, k=key: select_tab(k, user=True))
        tab_btns[key] = (lb, ul)
    tk.Frame(body, bg="#232a36", height=1).pack(fill="x", padx=8)

    pages = {k: tk.Frame(body, bg=BG) for k in ("items", "augs", "guide")}

    def make_rows(parent, n):
        rows = []
        for _ in range(n):
            fr = tk.Frame(parent, bg=CARD, cursor="arrow")
            top = tk.Frame(fr, bg=CARD)
            top.pack(fill="x")
            sc = tk.Label(top, text="", bg=CARD_HI, fg=FG, font=F["score"], width=3)
            sc.pack(side="left", padx=(0, 6), fill="y")
            nm = tk.Label(top, text="", bg=CARD, fg=FG, font=F["name"], anchor="w")
            nm.pack(side="left")
            meta = tk.Label(top, text="", bg=CARD, fg=SUB, font=F["small"], anchor="e")
            meta.pack(side="right", padx=6)
            rs = tk.Label(fr, text="", bg=CARD, fg=SUB, font=F["small"], anchor="w", justify="left")
            rs.pack(fill="x", padx=(6, 6), pady=(0, 3))
            full = {"text": ""}
            for w in (fr, nm, rs, meta, sc):
                hover(w, lambda full=full: full["text"])
            rows.append({"fr": fr, "sc": sc, "nm": nm, "meta": meta, "rs": rs, "full": full})
        return rows

    def short(text, n):
        n = int(n * st["k"] ** -0.2) if st["k"] > 1 else int(n / st["k"])
        if LANG == "en":
            n = int(n * 1.9)          # 英文字母比汉字窄
        return text if len(text) <= n else text[:n - 1] + "…"

    # 出装页：战术（最多 2 条）＋鞋子＋装备
    shop_lbl = tk.Label(pages["items"], text="", bg="#2a2412", fg=GOLD, font=F["tip"], anchor="w", justify="left",
                        padx=6, pady=3)
    wraps.append(shop_lbl)
    tips_box = tk.Frame(pages["items"], bg=BG)
    tips_box.pack(fill="x")
    tip_lbls = []
    for _ in range(2):
        lb = tk.Label(tips_box, text="", bg=BG, fg=FG, font=F["tip"], anchor="w", justify="left")
        wraps.append(lb)
        tip_lbls.append(lb)
    item_rows = make_rows(pages["items"], 4)

    # 增幅页
    aug_head = tk.Label(pages["augs"], text="", bg=BG, fg=SUB, font=F["small"], anchor="w")
    aug_head.pack(fill="x", pady=(0, 2))
    aug_rows = make_rows(pages["augs"], 4)
    mine_lbl = tk.Label(pages["augs"], text="", bg=BG, fg=DIM, font=F["small"], anchor="w", justify="left")
    wraps.append(mine_lbl)
    enemy_lbl = tk.Label(pages["augs"], text="", bg=BG, fg=ORANGE, font=F["small"], anchor="w", justify="left")
    wraps.append(enemy_lbl)

    # 玩法页
    guide_lbl = tk.Label(pages["guide"], text="", bg=CARD, fg=FG, font=F["tip"], anchor="w", justify="left",
                         padx=8, pady=6)
    guide_lbl.pack(fill="x")
    wraps.append(guide_lbl)

    footer = tk.Label(body, text="", bg=BG, fg=DIM, font=F["small"], anchor="w", padx=8, cursor="hand2")
    footer.pack(fill="x", pady=(0, 4))
    footer.bind("<Button-1>", lambda e: switch_bracket())

    def footer_tip():
        so = S()
        up = getattr(engine, "updater", None)
        lines = [tr('海斗助手 v{0}').format(APP_VERSION), tr('游戏数据 {0}').format(engine.gd.version)]
        if so is not None and so.version:
            lines.append(tr('海斗胜率 ARAMKit {0}（{1}）').format(so.version.get('version', ''), so.version.get('dataDate', '')))
        if st.get("data_msg"):
            lines.append(st["data_msg"])
        elif up is not None and up.last_result:
            lines.append(up.last_result)
        if getattr(engine.gd, "am_matched", 0):
            lines.append(tr("增幅多语言名称 / 国服选取率 / 推荐组合：") + AM_ATTRIBUTION)
        lines.append(tr("点一下切换 全部分段 / 高分段"))
        return "\n".join(lines)
    hover(footer, footer_tip)

    # ---------- 展开 / 收起 ----------
    def set_expanded(flag):
        flag = flag or st["pinned"]
        if flag == st["expanded"]:
            return
        st["expanded"] = flag
        if flag:
            mini.pack_forget()
            body.pack(fill="both", expand=True)
        else:
            body.pack_forget()
            mini.pack(fill="x")
        fit()

    def pointer_inside():
        try:
            px, py = root.winfo_pointerxy()
            x, y = root.winfo_rootx(), root.winfo_rooty()
            return x <= px < x + root.winfo_width() and y <= py < y + root.winfo_height()
        except tk.TclError:
            return False

    def auto_collapse():
        """每次 poll 调用：鼠标停留 0.6 秒才展开；离开 1 秒且没有需要看的内容就收起"""
        now = time.time()
        inside = pointer_inside()
        if inside:
            st["inside_since"] = st["inside_since"] or now
        else:
            if st["inside_since"] is not None:
                st["left_at"] = now
            st["inside_since"] = None
            kill_tip()                      # 鼠标不在窗口上，提示框一律关掉
        if st["pinned"]:
            set_expanded(True)
            return
        if not st["expanded"]:
            if inside and now - st["inside_since"] >= 0.6:
                st["hold_until"] = 0.0
                set_expanded(True)
            return
        rec = current["rec"]
        busy = bool(rec and rec.get("auto_cand"))          # 屏幕上正在三选一
        if inside or busy or manual_win["w"] is not None:
            return
        if now < st["hold_until"] or now - st["left_at"] < 1.0:
            return
        set_expanded(False)

    def toggle_pin():
        st["pinned"] = not st["pinned"]
        pin_btn.config(fg=GOLD if st["pinned"] else SUB)
        if st["pinned"]:
            set_expanded(True)

    # ---------- 识别 / 分段 / 设置菜单 ----------
    def S():            # 数据更新后 advisor.stats 会换成新的，所以每次现取
        return getattr(engine.advisor, "stats", None)
    stats_obj = S()
    scan_on = threading.Event()
    auto_default = bool(cfg.get("auto_scan", False) or getattr(engine, "auto_scan_default", False))
    if auto_default:
        scan_on.set()
    auto_var = tk.IntVar(value=1 if auto_default else 0)
    bracket_var = tk.StringVar(value=getattr(stats_obj, "dataset", "all"))
    size_var = tk.DoubleVar(value=st["k"])

    def force_scan():
        if scanner is not None and scanner.available:
            set_status(tr("识别中…"))
            st["status_hold"] = time.time() + 15
            engine.scanning = True
            scanner.force.set()
        else:
            status.config(text=tr("识别不可用：") + (scanner.error if scanner else tr("已关闭")))

    def toggle_auto():
        scan_on.set() if auto_var.get() else scan_on.clear()
        c = load_ui_cfg()
        c["auto_scan"] = bool(auto_var.get())
        save_ui_cfg(c)

    def switch_bracket(ds=None):
        so = S()
        if so is None:
            return
        ds = ds or ("all" if so.dataset == "high" else "high")
        so.set_dataset(ds)
        bracket_var.set(ds)
        c = load_ui_cfg()
        c["bracket"] = ds
        save_ui_cfg(c)
        status.config(text=tr("重新读取胜率…"))

    menu = tk.Menu(root, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", activeforeground=FG,
                   font=F["small"], bd=0)
    sizes = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
    for label, k in ((tr("小"), 0.85), (tr("中"), 1.0), (tr("大"), 1.2), (tr("特大"), 1.45)):
        sizes.add_radiobutton(label=label, variable=size_var, value=k, command=lambda k=k: set_scale(k))
    menu.add_cascade(label=tr("字号"), menu=sizes)
    if stats_obj is not None:
        br = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
        br.add_radiobutton(label=tr("全部分段"), variable=bracket_var, value="all", command=lambda: switch_bracket("all"))
        br.add_radiobutton(label=tr("高分段"), variable=bracket_var, value="high", command=lambda: switch_bracket("high"))
        menu.add_cascade(label=tr("胜率数据分段"), menu=br)
    brief_var = tk.BooleanVar(value=st["brief"])

    def toggle_brief():
        st["brief"] = brief_var.get()
        c = load_ui_cfg()
        c["brief"] = st["brief"]
        save_ui_cfg(c)
        if current.get("rec"):
            show(current["rec"], flash=False)
    menu.add_checkbutton(label=tr("显示战况条（连招 / 战局 / 威胁 / 玩法）"), variable=brief_var, command=toggle_brief)
    menu.add_checkbutton(label=tr("一直自动识别三选一（较耗 CPU）"), variable=auto_var, command=toggle_auto)
    menu.add_command(label=tr("手动输入增幅…"), command=lambda: open_manual())
    habits_var = tk.BooleanVar(value=engine.habits.enabled)

    def toggle_habits():
        engine.habits.enabled = bool(habits_var.get())
        c = load_ui_cfg()
        c["habits"] = engine.habits.enabled
        save_ui_cfg(c)
        engine.last_sig = None
        engine.wake.set()

    def clear_habits():
        engine.habits.clear()
        set_status(tr("已清除习惯记录"))
        st["status_hold"] = time.time() + 5
        engine.last_sig = None
        engine.wake.set()
    hm = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
    hm.add_checkbutton(label=tr("按我的习惯调整推荐（只存本机）"), variable=habits_var, command=toggle_habits)
    hm.add_command(label=tr("从游戏客户端导入历史对局"),
                   command=lambda: (set_status(tr("读取客户端对局记录…")), engine.import_history_async(manual=True)))
    hm.add_command(label=tr("清除我的习惯记录"), command=clear_habits)

    def open_stats():
        w = tk.Toplevel(root)
        w.title(tr("我的战绩"))
        w.attributes("-topmost", True)
        w.configure(bg=BG)
        txt = tk.Text(w, bg=CARD, fg=FG, font=F["small"], width=78, height=26, bd=0, padx=10, pady=8, wrap="none")
        txt.insert("1.0", engine.habits.report(engine.gd))
        txt.config(state="disabled")
        txt.pack(fill="both", expand=True)
        st["hold_until"] = time.time() + 3
    menu.add_command(label=tr("我的战绩…"), command=open_stats)

    def open_riotdb():
        db = engine.riotdb
        w = tk.Toplevel(root)
        w.title(tr("自建数据库（Riot 开发者密钥）"))
        w.attributes("-topmost", True)
        w.configure(bg=BG, padx=12, pady=10)
        st["hold_until"] = time.time() + 3

        def lab(text, **kw):
            lb = tk.Label(w, text=text, bg=BG, fg=kw.pop("fg", FG), font=F["small"], anchor="w", justify="left",
                          wraplength=int(360 * dpi * st["k"]), **kw)
            lb.pack(fill="x", pady=(4, 0))
            return lb
        lab(tr("用你自己的 Riot 开发者密钥，在不打游戏时于背景收集海斗对局，攒够数据后按你的段位给出装 / 增幅加权。"
               "密钥只存在本机。到 developer.riotgames.com 登录后即可免费取得（开发者密钥每 24 小时要更新一次）。"), fg=SUB)
        lab(tr("Riot 开发者密钥（RGAPI-…）"))
        key = tk.Entry(w, show="•", bg=CARD, fg=FG, insertbackground=FG, relief="flat", font=F["small"])
        key.insert(0, db.cfg.get("key", ""))
        key.pack(fill="x", ipady=3)
        lab(tr("你的服务器"))
        plat = tk.StringVar(value=db.cfg.get("platform", "SG2"))
        om = tk.OptionMenu(w, plat, *RIOT_PLATFORMS)
        om.config(bg=CARD, fg=FG, highlightthickness=0, relief="flat", font=F["small"])
        om.pack(anchor="w")
        lab(tr("你的 Riot ID（名字#TAG，留空＝进游戏时自动读取）"))
        rid = tk.Entry(w, bg=CARD, fg=FG, insertbackground=FG, relief="flat", font=F["small"])
        rid.insert(0, db.cfg.get("riot_id", ""))
        rid.pack(fill="x", ipady=3)
        en = tk.BooleanVar(value=db.cfg.get("enabled", False))
        rk = tk.BooleanVar(value=db.cfg.get("ranks", True))
        for var, text in ((en, tr("启用收集（只在不打游戏时）")), (rk, tr("记录每个玩家的段位（可以按段位统计，收集速度约慢 10 倍）"))):
            tk.Checkbutton(w, text=text, variable=var, bg=BG, fg=FG, selectcolor=CARD, activebackground=BG,
                           activeforeground=FG, font=F["small"], anchor="w").pack(fill="x")
        info = lab("", fg=GOLD)

        def refresh():
            if not w.winfo_exists():
                return
            n = db.total_games()
            tier = db.cfg.get("my_tier")
            info.config(text=tr('已收集约 {0} 局').format(n) + (tr('　你的段位：{0}').format(tier_name(tier)) if tier else "") +
                        ("\n" + db.status if db.status else ""))
            w.after(3000, refresh)

        def save():
            changed = key.get().strip() != db.cfg.get("key") or plat.get() != db.cfg.get("platform") or \
                rid.get().strip() != db.cfg.get("riot_id", "")
            if changed:
                db.cfg.pop("my_puuid", None)
                db.cfg.pop("my_tier", None)
            if key.get().strip() != db.cfg.get("key"):
                en.set(True)                # 换了新密钥＝要继续收集（过期时会被自动关掉）
            db.save_cfg(key=key.get().strip(), platform=plat.get(), riot_id=rid.get().strip(),
                        enabled=bool(en.get()), ranks=bool(rk.get()))
            db.status = tr("已保存，会在不打游戏时开始收集")
        tk.Label(w, text=tr("保存"), bg="#2b3a57", fg=FG, font=F["small"], padx=12, pady=4, cursor="hand2").pack(
            anchor="e", pady=(8, 0))
        w.winfo_children()[-1].bind("<Button-1>", lambda e: save())
        refresh()
    menu.add_command(label=tr("自建数据库（Riot 密钥）…"), command=open_riotdb)
    menu.add_cascade(label=tr('我的习惯（{0} 局）').format(len(engine.habits.games)), menu=hm)
    lang_var = tk.StringVar(value=LANG)

    def switch_lang(lg):
        c = load_ui_cfg()
        if c.get("ui_lang", "zh") == lg:
            return
        c["ui_lang"] = lg
        c.pop("data_lang", None)       # 游戏数据语言跟着界面语言走（英文界面＝英文客户端名称）
        save_ui_cfg(c)
        set_status("重新打开后生效" if lg == "zh" else "Restart to apply")
        st["status_hold"] = time.time() + 30
    lm = tk.Menu(menu, tearoff=0, bg="#1b2130", fg=FG, activebackground="#2b3a57", font=F["small"])
    lm.add_radiobutton(label="中文", variable=lang_var, value="zh", command=lambda: switch_lang("zh"))
    lm.add_radiobutton(label="English", variable=lang_var, value="en", command=lambda: switch_lang("en"))
    menu.add_cascade(label="语言 / Language", menu=lm)
    menu.add_separator()

    def check_update():
        up = getattr(engine, "updater", None)
        if up is None:
            status.config(text=tr("演示模式不检查更新"))
            return
        status.config(text=tr("检查更新中…"))
        st["status_hold"] = time.time() + 20
        up.check_now()
    menu.add_command(label=tr('检查更新（当前 v{0}）').format(APP_VERSION), command=check_update)
    menu.add_command(label=tr("关闭海斗助手"), command=root.destroy)

    def open_menu():
        st["hold_until"] = time.time() + 4
        menu.tk_popup(menu_btn.winfo_rootx(), menu_btn.winfo_rooty() + menu_btn.winfo_height())

    # ---------- 手动输入（小窗） ----------
    manual_win = {"w": None}
    entries = {}
    manual_vals = {"mine": "", "cand": "", "ally": "", "enemy": ""}

    def apply_all():
        for k, e in entries.items():
            manual_vals[k] = e.get()
            engine.set_manual(k, e.get())

    def open_manual():
        if manual_win["w"] is not None:
            manual_win["w"].lift()
            return
        w = tk.Toplevel(root)
        w.overrideredirect(True)
        w.attributes("-topmost", True)
        w.configure(bg=BG, highlightthickness=1, highlightbackground="#2a3140")
        tk.Label(w, text=tr("手动输入增幅（逗号或空格分隔，可只写关键字）"), bg=HEAD, fg=GOLD, font=F["small"],
                 anchor="w", padx=8, pady=4).pack(fill="x")
        for key, label in (("cand", tr("三选一候选")), ("mine", tr("我的增幅")), ("ally", tr("队友增幅")), ("enemy", tr("敌方增幅"))):
            row = tk.Frame(w, bg=BG)
            row.pack(fill="x", padx=8, pady=2)
            tk.Label(row, text=label, width=8, bg=BG, fg=SUB, font=F["small"], anchor="w").pack(side="left")
            e = tk.Entry(row, bg="#1f2637", fg=FG, insertbackground=FG, relief="flat", font=F["small"], width=26)
            e.insert(0, manual_vals.get(key, ""))
            e.pack(side="left", fill="x", expand=True, ipady=2)
            e.bind("<Return>", lambda ev: apply_all())
            entries[key] = e
        btns = tk.Frame(w, bg=BG)
        btns.pack(fill="x", padx=8, pady=(4, 8))

        def close():
            apply_all()
            entries.clear()
            w.destroy()
            manual_win["w"] = None
        tk.Label(btns, text=tr("套用并关闭"), bg="#2b3a57", fg=FG, font=F["small"], padx=10, pady=3,
                 cursor="hand2").pack(side="right")
        btns.winfo_children()[-1].bind("<Button-1>", lambda e: close())
        w.update_idletasks()
        x = root.winfo_rootx() - w.winfo_reqwidth() - 6
        w.geometry(f"+{max(0, x)}+{root.winfo_rooty()}")
        manual_win["w"] = w

    # ---------- 填内容 ----------
    current = {"rec": None}

    def brief(reason):
        """卡片上的一行理由：胜率已在右上角显示，这里只留原因"""
        t = re.sub(r"(网上胜率|胜率) [\d.]+%（比平均[+-][\d.]+%）[，,]?", "", reason)
        t = re.sub(r"(?i)win rate [\d.]+% \([+-][\d.]+% vs avg\),? ?", "", t)
        t = re.sub(r"[，,]\s*$", "", t.replace(tr("主流路线的下一件，"), tr("主流路线的下一件，")).strip(tr("，, ")))
        return t or reason

    def fill_rows(rows, data, cand=False, before=None):
        for i, r in enumerate(rows):
            r["fr"].pack_forget()
            if i >= len(data):
                continue
            d = data[i]
            star = "★ " if cand and i == 0 else ""
            r["sc"].config(text=str(d["score"]), fg=score_color(d["score"]))
            r["nm"].config(text=star + d["name"], fg=GOLD if cand and i == 0 else FG)
            meta = []
            if d.get("wr"):
                meta.append(f"{d['wr'] * 100:.1f}%")
            if d.get("hint"):
                meta.append(d["hint"])
            elif not d.get("known", True):
                meta.append(tr("未收录"))
            r["meta"].config(text=" · ".join(meta))
            r["rs"].config(text=short(brief(d["reason"]), 26))
            r["full"]["text"] = d["reason"] + (f"\n{d['stat_text']}" if d.get("stat_text") else "")
            if before is not None:
                r["fr"].pack(fill="x", pady=2, before=before)
            else:
                r["fr"].pack(fill="x", pady=2)

    def show_select(sel):
        """选英雄阶段：你的英雄 + 备选席，按分数排"""
        cands = sel.get("cands", [])
        if not cands:
            return
        best = cands[0]
        needs = sel.get("needs") or []
        summary.config(text=tr("选英雄") + (" · " + tr('队伍缺：{0}').format(tr("、").join(needs)) if needs else ""))
        alert.pack_forget()
        brief_box.pack_forget()
        summary.pack(fill="x", pady=(5, 0), before=tabs_bar)
        shop_lbl.pack_forget()
        for lb in tip_lbls:
            lb.pack_forget()
        mine = next((c for c in cands if c.get("mine")), None)
        if mine and best is not mine and best["score"] - mine["score"] >= 3:
            tip = tr('★ 建议从备选席换成 {0}（{1} 分，你现在的 {2} {3} 分）').format(
                best["name"], best["score"], mine["name"], mine["score"])
        elif mine:
            tip = tr('保持 {0} 就好（备选席里没有明显更好的）').format(mine["name"])
        else:
            tip = tr('★ 推荐 {0}').format(best["name"])
        tip_lbls[0].config(text=tip)
        tip_lbls[0].pack(fill="x", pady=(0, 1))
        rows = cands[:4]
        if mine and mine not in rows:          # 你自己的英雄一定要看得到（备选席很多时会被挤出前 4）
            rows = cands[:3] + [mine]
        fill_rows(item_rows, rows)
        if st["tab"] != "items":
            select_tab("items")
        mini.config(text=tip, fg=GOLD)
        st["hold_until"] = time.time() + 8
        set_expanded(True)
        fit()

    def choose(i):
        rec = current["rec"]
        if not rec or not rec.get("cand_mode") or i >= len(rec["augs"]):
            return
        name = rec["augs"][i]["name"]
        mine = [x for x in re.split(r"[,，、\s]+", manual_vals.get("mine", "")) if x]
        if name not in mine:
            mine.append(name)
        manual_vals["mine"] = tr("，").join(mine)
        manual_vals["cand"] = ""
        engine.set_manual("mine", manual_vals["mine"])
        engine.set_manual("cand", "")
        engine.set_auto([])

    for i, r in enumerate(aug_rows):
        for w in (r["fr"], r["nm"], r["sc"], r["rs"], r["meta"]):
            w.bind("<Button-1>", lambda e, i=i: choose(i))

    def show(rec, flash=True):
        current["rec"] = rec
        mine_names = rec.get("my_augs", [])
        manual_vals["mine"] = tr("，").join(mine_names)
        summary.config(text=rec.get("summary", "").replace(tr("｜"), " · ").replace(tr("网上 "), ""))
        has_brief = show_brief(rec.get("brief"))
        if has_brief:                              # 战况条已含局势，摘要行收起来省空间
            summary.pack_forget()
        else:
            summary.pack(fill="x", pady=(5, 0), before=tabs_bar)
        # 紧急提示（人数差、残血…）；战况条已经显示了就不重复
        tips = rec.get("tips", [])
        urgent = [x for x in tips if x[2]]
        if urgent and not has_brief:
            alert.config(text="⚠ " + urgent[0][1])
            alert.pack(fill="x", padx=8, pady=(4, 0), after=summary)
        else:
            alert.pack_forget()
        # 阵亡购物清单（复活前买什么）
        shop = rec.get("shop")
        shop_text = shop_line(shop)
        rv = st.get("review")
        if shop_text:
            shop_lbl.config(text=shop_text)
            shop_lbl.pack(fill="x", pady=(0, 3), before=tips_box)
        elif rv and time.time() < rv[1]:
            pass                                   # 赛后复盘还在显示
        else:
            shop_lbl.pack_forget()
        # 出装页
        normal = [] if has_brief else [x for x in tips if not x[2]][:2]
        for i, lb in enumerate(tip_lbls):
            lb.pack_forget()
            if i < len(normal):
                lb.config(text="▸" + normal[i][1])
                lb.pack(fill="x", pady=(0, 1))
        fill_rows(item_rows, rec.get("items", [])[:4])
        # 增幅页
        cand = rec.get("cand_mode")
        aug_head.config(text=(tr("识别到三选一 · ★ 推荐 · 点卡片记为已选") if rec.get("auto_cand") else
                              tr("三选一评分 · ★ 推荐 · 点卡片记为已选")) if cand else tr("当前局势推荐的增幅"),
                        fg=GOLD if cand else SUB)
        mine_lbl.config(text=tr("已选增幅：") + (tr("、").join(mine_names) if mine_names else tr("（还没有）")))
        mine_lbl.pack(fill="x", pady=(2, 0))
        ea = rec.get("enemy_augs") or []
        if ea:
            enemy_lbl.config(text=tr("敌方增幅：") + "\n" + "\n".join(
                tr("{0}「{1}」").format(x["who"], x["aug"]) + (" → " + x["fix"] if x["fix"] else "") for x in ea[:6]))
            enemy_lbl.pack(fill="x", pady=(2, 0), after=mine_lbl)
        elif not rec.get("eaug_visible") and rec.get("game_time", 0) > 420:
            enemy_lbl.config(text=tr("游戏没提供敌方增幅：可在 ⋯ → 手动输入增幅 填写"), fg=DIM)
            enemy_lbl.pack(fill="x", pady=(2, 0), after=mine_lbl)
        else:
            enemy_lbl.pack_forget()
        if ea:
            enemy_lbl.config(fg=ORANGE)
        fill_rows(aug_rows, rec.get("augs", [])[:3 if cand else 4], cand, before=mine_lbl)
        # 玩法页
        g = rec.get("guide") or {}
        lines = [x for x in (g.get("habit"), g.get("balance"), g.get("skills"), g.get("spells")) if x]
        lines += [tr('连招  {0}\n        {1}').format(c, note) for c, note in g.get("combos", [])]
        if g.get("style"):
            lines.append(tr("玩法  ") + g["style"])
        guide_lbl.config(text="\n".join(lines) or tr("（暂无这个英雄的玩法数据）"))
        # 分段 / 数据来源
        so = S()
        gv = ".".join(str(engine.gd.version).split(".")[:2])
        if so is not None:
            ver = (so.version or {}).get("version", "")
            tier = tr("高分段") if so.dataset == "high" else tr("全部分段")
            footer.config(text=tr('游戏 {0} · ARAMKit {1} · {2} ⇄').format(gv, ver, tier) if ver else tr('游戏 {0} · {1} ⇄').format(gv, tier))
        else:
            footer.config(text=tr('游戏 {0}').format(gv))
        # 自动选分页：出现新的三选一（或重骰）时切到增幅一次；你自己切走就不再拉回来
        cand_key = tuple(a["name"] for a in rec.get("augs", [])[:3]) if cand else None
        if cand:
            if cand_key != st.get("cand_jumped"):
                st["cand_jumped"] = cand_key
                if st["tab"] != "augs":
                    st["tab_before_cand"] = st["tab"]
                    select_tab("augs")
        elif st["tab_before_cand"]:
            if st["tab"] == "augs":                # 只有还停在增幅页时才切回原来那页
                select_tab(st["tab_before_cand"])
            st["tab_before_cand"] = None
            st["cand_jumped"] = None
        elif shop_text:
            if st["tab"] != "items":
                select_tab("items")
        elif not st["user_tab"]:
            select_tab("guide" if rec.get("game_time", 999) < 90 else "items")
        # 单行模式
        its = [x for x in rec.get("items", []) if not x.get("boots")]
        boots = next((x for x in rec.get("items", []) if x.get("boots")), None)
        if shop_text and not cand:
            mini.config(text=shop_text, fg=GOLD)
        elif urgent:
            mini.config(text="⚠ " + urgent[0][1], fg=ORANGE)
        elif cand and rec.get("augs"):
            mini.config(text=tr('★ 选 {0}（{1}）').format(rec['augs'][0]['name'], rec['augs'][0]['score']), fg=GOLD)
        else:
            parts = []
            if its:
                parts.append(f"▶ {its[0]['name']} {its[0]['score']}")
            if boots:
                parts.append(boots["name"])
            line = "   ".join(parts) or tr("等待推荐…")
            bf = dict((x[0], x[1]) for x in rec.get("brief") or [])
            thr = bf.get(tr("威胁"), "").split(" · ")[0]
            hot_aug = next((x[1] for x in rec.get("brief") or [] if x[0] == tr("敌增幅") and x[2]), None)
            extra = "⚠" + hot_aug if hot_aug else \
                "   ".join(x for x in (bf.get(tr("连招")), "⚠" + thr if thr else "") if x)
            mini.config(text=line + ("\n" + extra if st["brief"] and extra else ""), fg=FG)
        # 只有和你有关的推荐真的变了才弹开（别人买装备、升级不弹）
        its_key = tuple(x["name"] for x in its[:2])
        key = (its_key, boots["name"] if boots else None, bool(cand),
               tuple(x["name"] for x in rec.get("augs", [])[:3]) if cand else None,
               tuple(sorted(x["key"] for x in rec.get("enemy_augs") or [])))     # 敌方拿到新增幅也弹开
        if shop_text and not st.get("shop_shown"):       # 刚阵亡：展开到复活为止
            st["hold_until"] = time.time() + min(30, max(5, shop.get("respawn", 8)))
            set_expanded(True)
        st["shop_shown"] = bool(shop_text)
        if flash and key != st["last_key"]:
            st["hold_until"] = max(st["hold_until"], time.time() + 5)
            set_expanded(True)
        st["last_key"] = key
        fit()

    def poll():
        try:
            engine.overlay_rect = (root.winfo_rootx(), root.winfo_rooty(),
                                   root.winfo_rootx() + root.winfo_width(), root.winfo_rooty() + root.winfo_height())
        except tk.TclError:
            pass
        try:
            msgs = []
            while True:
                msgs.append(engine.q.get_nowait())
        except queue.Empty:
            pass
        last_rec = max((i for i, (k, _) in enumerate(msgs) if k == "rec"), default=None)
        for i, (kind, payload) in enumerate(msgs):
            hold = time.time() < st.get("status_hold", 0)
            if kind == "rec":
                if i != last_rec:        # 一次来了好几个推荐：只画最新的
                    continue
                dot.config(fg=GREEN)
                show(payload, flash=not payload.get("quiet"))
                if not hold:
                    set_status("")
            elif kind == "review":         # 赛后复盘
                st["review"] = (payload, time.time() + 25)
                shop_lbl.config(text="📋 " + payload["text"] + ("\n" + payload["detail"] if payload.get("detail") else ""))
                shop_lbl.pack(fill="x", pady=(0, 3), before=tips_box)
                if st["tab"] != "items":
                    select_tab("items")
                mini.config(text="📋 " + payload["text"], fg=GOLD)
                st["hold_until"] = time.time() + 20
                set_expanded(True)
                fit()
            elif kind == "select":         # 选英雄阶段
                dot.config(fg=GOLD)
                show_select(payload)
            elif kind == "scan":           # 三选一识别的进度 / 结果
                set_status(short(payload, 16))
                st["status_hold"] = time.time() + (15 if payload == tr("识别中…") else 4)
            elif kind == "upgraded":       # 一键更新完成
                st["app_new"], st["upgrading"] = None, False
                set_status(tr("已更新 ✓ 请重新打开"))
                st["status_hold"] = time.time() + 10 ** 9
                st["data_msg"] = payload
            elif kind == "appupd":         # 程序有新版本：点一下直接更新
                st["app_new"] = payload
                if not hold:
                    set_status("")
            elif kind == "data":           # 数据版本检查 / 更新
                st["data_msg"] = payload
                if payload.startswith(tr("更新失败")):
                    st["upgrading"] = False
                set_status(tr("数据已更新 ✓") if payload.startswith(tr("数据已更新")) else short(payload, 14))
                st["status_hold"] = time.time() + 8
                st["hold_until"] = time.time() + 6
            else:
                if payload.startswith(tr("等待")):
                    dot.config(fg=GREY)
                if not hold:               # 正在显示的重要消息（识别中、更新结果…）不被一般状态盖掉
                    set_status("" if payload == tr("监控中") else short(payload, 14))
        auto_collapse()
        root.after(60 if engine.scanning else 300, poll)     # 识别中刷新快一点

    set_scale(st["k"])
    select_tab("items")
    st["hold_until"] = time.time() + 5
    stop = threading.Event()
    threading.Thread(target=engine.run, args=(stop,), daemon=True).start()
    start_scanner(engine, scanner, stop, scan_on)
    root.after(300, poll)
    root.mainloop()
    stop.set()


# --------------------------------------------------------------------------------------
# 网页检视（手机 / 第二屏幕；独占全屏时用）
# --------------------------------------------------------------------------------------
def lan_ip():
    import socket
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:  # noqa
        return "127.0.0.1"


def start_web(engine, port=8765):
    import html
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

    def page():
        rec = engine.history[-1] if engine.history else None
        esc = html.escape

        def rows(data, cand=False):
            out = []
            for i, d in enumerate(data[:5]):
                col = "#4ade80" if d["score"] >= 80 else "#facc15" if d["score"] >= 60 else "#94a3b8"
                star = "★ " if cand and i == 0 else ""
                bits = ([tr('胜率{0:.1f}%').format(d['wr'] * 100)] if d.get("wr") else []) + ([d["hint"]] if d.get("hint") else [])
                hint = f' <small style="color:#9aa4b5">{esc(" · ".join(bits))}</small>' if bits else ""
                out.append(f'<div class="c"><div class="t"><b>{star}{esc(d["name"])}{hint}</b>'
                           f'<span style="color:{col}">{d["score"]}</span></div><p>{esc(d["reason"])}</p></div>')
            return "".join(out)
        if not rec:
            content = tr("<p class='s'>等待对局…</p>")
        else:
            at = (tr("识别到三选一（★ 推荐）") if rec["cand_mode"] else tr("推荐增幅"))
            tips = "".join(f"<div class='c' style='color:{'#fb923c' if u else '#e8ecf3'}'>{'⚠' if u else '•'} {esc(x)}</div>"
                           for _, x, u in rec.get("tips", []))
            g = rec.get("guide") or {}
            gl = [x for x in (g.get("balance"), g.get("skills"), g.get("spells")) if x] + \
                 [tr('连招：{0}｜{1}').format(c, n) for c, n in g.get("combos", [])] + ([tr('玩法：{0}').format(g['style'])] if g.get("style") else [])
            guide = "".join(f"<div class='c'>{esc(x)}</div>" for x in gl)
            content = (tr("<p class='ch'>[{0}] {1}</p><p class='s'>{2}</p><h3>英雄玩法</h3>{3}<h3>战术建议</h3>{4}<h3>推荐装备</h3>{5}<h3>{6}</h3>{7}").format(rec['time'], esc(tr('；').join(rec['changes'][:3])), esc(rec['summary']), guide, tips, rows(rec['items']), at, rows(rec['augs'], rec['cand_mode'])))
        return (tr("<!doctype html><meta charset='utf-8'><meta name='viewport' content='width=device-width'>"
                "<meta http-equiv='refresh' content='2'><title>海斗助手</title><style>"
                "body{background:#12161f;color:#e8ecf3;font-family:system-ui,sans-serif;margin:12px;font-size:16px}"
                "h3{margin:14px 0 6px}.c{background:#1a2030;border-radius:8px;padding:8px 10px;margin:6px 0}"
                ".t{display:flex;justify-content:space-between;font-size:17px}.t span{font-weight:700;font-size:20px}"
                "p{margin:4px 0;color:#9aa4b5;font-size:14px}.ch{color:#c8aa6e}.s{font-size:13px}</style>"
                "<h2 style='color:#c8aa6e;margin:0'>⚔ 海斗助手</h2>") + content)

    class H(BaseHTTPRequestHandler):
        def do_GET(self):
            body = page().encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass

    try:
        srv = ThreadingHTTPServer(("0.0.0.0", port), H)
    except OSError as e:
        print(tr('[网页] 端口 {0} 被占用，网页检视没有开启（{1}）').format(port, e))
        return None
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    url = f"http://{lan_ip()}:{port}"
    print(tr('[网页] 手机/平板连同一个 WiFi，浏览器开启：{0}').format(url))
    return url


# --------------------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser(description=tr("海斗助手：海克斯大乱斗实时出装/增幅推荐"))
    ap.add_argument("--mock", action="store_true", help=tr("使用模拟对局演示"))
    ap.add_argument("--console", action="store_true", help=tr("控制台文字模式"))
    ap.add_argument("--lang", default=None, help="数据语言（和游戏客户端一致）：zh_MY（默认）/ zh_TW / zh_CN / en_US …")
    ap.add_argument("--ui-lang", choices=["zh", "en"], default=None, help="界面语言 / interface language: zh / en")
    ap.add_argument("--interval", type=float, default=1.5, help=tr("轮询间隔秒数"))
    ap.add_argument("--alpha", type=float, default=0.88, help=tr("悬浮窗透明度 0.3~1"))
    ap.add_argument("--no-scan", action="store_true", help=tr("关闭屏幕识别三选一"))
    ap.add_argument("--no-stats", action="store_true", help=tr("不使用网上胜率数据"))
    ap.add_argument("--no-click", action="store_true", help=tr("不自动记录你点选的增幅"))
    ap.add_argument("--hotkey", default="F8", help=tr("识别三选一的快捷键（F1~F12），默认 F8"))
    ap.add_argument("--auto-scan", action="store_true", help=tr("一直自动识别三选一（较耗 CPU）"))
    ap.add_argument("--bracket", choices=["all", "high"], default=None, help=tr("胜率数据分段：all 全部 / high 高分段"))
    ap.add_argument("--web", action="store_true", help=tr("同时开启网页检视（手机/第二屏，埠 8765）"))
    ap.add_argument("--scale", type=float, default=None, help=tr("界面缩放，例如 1.3"))
    args = ap.parse_args()

    if sys.platform.startswith("win"):
        try:  # 高分屏下截图坐标与实际一致
            import ctypes
            ctypes.windll.shcore.SetProcessDpiAwareness(2)
        except Exception:  # noqa
            pass
        try:  # 降低本程序的 CPU 优先级，游戏永远优先
            import ctypes
            ctypes.windll.kernel32.SetPriorityClass(ctypes.windll.kernel32.GetCurrentProcess(), 0x4000)
        except Exception:  # noqa
            pass
    cfg = load_ui_cfg()
    set_lang(args.ui_lang or cfg.get("ui_lang", "zh"))
    args.lang = args.lang or cfg.get("data_lang") or default_data_lang(LANG)
    print(tr('海斗助手 v{0}').format(APP_VERSION))
    gd, stats = load_all(args.lang, args.bracket or load_ui_cfg().get("bracket", "all"), not args.no_stats)
    clean_old_cache(data_versions(gd, stats))
    source = MockGame() if args.mock else LiveSource()
    engine = Engine(gd, source, args.interval, stats)
    scanner = None
    if not args.no_scan:
        scanner = MockScanner(source, engine.advisor) if args.mock else ScreenScanner(engine.advisor)
        if not args.no_click:
            engine.clicker = MockClickWatcher(source) if args.mock else ClickWatcher()
        engine.hotkey = None if args.mock else HotkeyWatcher(args.hotkey)
        if engine.hotkey is not None and engine.hotkey.vk is None:
            print(tr('快捷键 {0} 不支持，只能用 F1~F12').format(args.hotkey))
        engine.auto_scan_default = args.auto_scan or args.mock   # 演示模式自动识别
    if not args.mock:
        start_updater(engine, args.lang, not args.no_stats, threading.Event())
    if args.web:
        start_web(engine)
    if args.console:
        run_console(engine, scanner)
        return
    try:
        run_overlay(engine, args.alpha, scanner, args.scale)
    except ImportError:
        print(tr("未找到 tkinter，改用控制台模式"))
        run_console(engine, scanner)


if __name__ == "__main__":
    main()
